1	import React from "react";
2	import { call, on, ago } from "../../api.js";
3	import GamePane from "../game/GamePane.jsx";
4	import "./studio.css";
5	
6	const EXAMPLES = [
7	  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
8	  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
9	  "Right-clicking with a blaze rod shoots a fireball where you look.",
10	];
11	
12	const PHASES = [
13	  ["spec", "Spec"],
14	  ["repo", "Repo"],
15	  ["build", "Build"],
16	  ["compile", "Compile"],
17	  ["deploy", "Deploy"],
18	  ["playtest", "Playtest"],
19	  ["fix", "Fix"],
20	  ["done", "Done"],
21	];
22	
23	const ROLE = {
24	  spec: "Spec agent",
25	  builder: "Builder",
26	  fixer: "Fixer",
27	  playtester: "Playtester",
28	  benana: "Benana",
29	};
30	
31	function phaseIndex(mod) {
32	  if (!mod) return -1;
33	  if (mod.phase === "fix") return 6;
34	  const i = PHASES.findIndex(([key]) => key === mod.phase);
35	  return i;
36	}
37	
38	function latestVerdict(mod) {
39	  const withVerdict = [...(mod?.attempts || [])].reverse().find((a) => a.verdict);
40	  return withVerdict?.verdict || null;
41	}
42	
43	export default function ModStudio({ onOpenWorkspace }) {
44	  const [mods, setMods] = React.useState([]);
45	  const [selectedId, setSelectedId] = React.useState(null);
46	  const [feed, setFeed] = React.useState([]);
47	  const [prompt, setPrompt] = React.useState("");
48	  const [seed, setSeed] = React.useState(false);
49	  const [busy, setBusy] = React.useState(false);
50	  const [error, setError] = React.useState("");
51	  const [lessons, setLessons] = React.useState([]);
52	  const selectedRef = React.useRef(null);
53	  selectedRef.current = selectedId;
54	
55	  React.useEffect(() => {
56	    call("studio:list")
57	      .then((list) => {
58	        setMods(list);
59	        if (list[0]) setSelectedId(list[0].id);
60	      })
61	      .catch((e) => setError(e.message));
62	    call("studio:lessons").then(setLessons).catch(() => {});
63	    const offs = [
64	      on("studio:mod", (mod) => {
65	        setMods((prev) => {
66	          const rest = prev.filter((m) => m.id !== mod.id);
67	          return [mod, ...rest].sort((a, b) => b.createdAt - a.createdAt);
68	        });
69	        if (mod.status === "passed") call("studio:lessons").then(setLessons).catch(() => {});
70	      }),
71	      on("studio:feed", ({ modId, item }) => {
72	        if (modId === selectedRef.current)
73	          setFeed((prev) => [...prev.slice(-599), item]);
74	      }),
75	    ];
76	    return () => offs.forEach((off) => off());
77	  }, []);
78	
79	  React.useEffect(() => {
80	    setFeed([]);
81	    if (!selectedId) return;
82	    call("studio:get", { id: selectedId })
83	      .then((mod) => setFeed(mod.feed.slice(-600)))
84	      .catch(() => {});
85	  }, [selectedId]);
86	
87	  const mod = mods.find((m) => m.id === selectedId) || null;
88	  const running = mods.some((m) => m.running);
89	
90	  const start = async () => {
91	    setBusy(true);
92	    setError("");
93	    try {
94	      const created = await call("studio:create", { prompt, seed });
95	      setSelectedId(created.id);
96	      setPrompt("");
97	    } catch (e) {
98	      setError(e.message);
99	    } finally {
100	      setBusy(false);
101	    }
102	  };
103	
104	  return (
105	    <div className="studio">
106	      <aside className="studio-side">
107	        <div className="studio-brand">
108	          <span className="brand">B</span>
109	          <strong>Mod Studio</strong>
110	        </div>
111	        <p className="studio-muted">
112	          Describe a Minecraft mod. Benana writes it, plays it in-game, and
113	          fixes what breaks.
114	        </p>
115	        <textarea
116	          className="studio-prompt"
117	          value={prompt}
118	          disabled={seed}
119	          onChange={(e) => setPrompt(e.target.value)}
120	          placeholder="A golden sword that launches mobs into the sky…"
121	          rows={4}
122	        />
123	        <div className="studio-examples">
124	          {EXAMPLES.map((ex) => (
125	            <button key={ex} onClick={() => setPrompt(ex)} title={ex}>
126	              {ex.split(" ").slice(0, 4).join(" ")}…
127	            </button>
128	          ))}
129	        </div>
130	        <label className="studio-seed">
131	          <input
132	            type="checkbox"
133	            checked={seed}
134	            onChange={(e) => setSeed(e.target.checked)}
135	          />
136	          <span>
137	            Seeded bug (fallback). Starts from a labeled buggy LaunchSword;
138	            the playtester and fixer still run for real.
139	          </span>
140	        </label>
141	        <button
142	          className="studio-go"
143	          disabled={busy || running || (!seed && prompt.trim().length < 8)}
144	          onClick={start}
145	        >
146	          {running ? "A mod is running…" : "Build and playtest"}
147	        </button>
148	        {error && <div className="studio-error">{error}</div>}
149	
150	        <h4>Mods</h4>
151	        <div className="studio-mods">
152	          {mods.map((m) => (
153	            <button
154	              key={m.id}
155	              className={`studio-mod ${m.id === selectedId ? "active" : ""}`}
156	              onClick={() => setSelectedId(m.id)}
157	            >
158	              <span className={`pill ${m.status}`}>{m.status}</span>
159	              <strong>{m.name}</strong>
160	              <small>
161	                {m.attempts.length} attempt{m.attempts.length === 1 ? "" : "s"}{" "}
162	                · {ago(m.createdAt)} ago{m.seed ? " · seeded" : ""}
163	              </small>
164	            </button>
165	          ))}
166	          {!mods.length && <p className="studio-muted">No mods yet.</p>}
167	        </div>
168	
169	        {lessons.length > 0 && (
170	          <>
171	            <h4>Learned by the fixer</h4>
172	            <ul className="studio-lessons">
173	              {lessons.slice(-4).map((l) => (
174	                <li key={l.at}>{l.lesson}</li>
175	              ))}
176	            </ul>
177	          </>
178	        )}
179	        <button className="studio-link" onClick={onOpenWorkspace}>
180	          Open repository workspace
181	        </button>
182	      </aside>
183	
184	      <main className="studio-main">
185	        <Stepper mod={mod} />
186	        <GamePane showLog={false} />
187	        <Feed feed={feed} mod={mod} />
188	      </main>
189	
190	      <aside className="studio-inspector">
191	        {mod ? <Inspector mod={mod} /> : <p className="studio-muted">Describe a mod to start.</p>}
192	      </aside>
193	    </div>
194	  );
195	}
196	
197	function Stepper({ mod }) {
198	  const current = phaseIndex(mod);
199	  const done = mod?.status === "passed";
200	  const failed = ["failed", "stopped"].includes(mod?.status);
201	  return (
202	    <div className="studio-stepper">
203	      {PHASES.map(([key, label], i) => (
204	        <div
205	          key={key}
206	          className={`step ${i < current || (done && i <= current) ? "done" : ""} ${
207	            i === current && !done ? (failed ? "failed" : "current") : ""
208	          }`}
209	        >
210	          <span className="dot" />
211	          {label}
212	        </div>
213	      ))}
214	      {mod && (
215	        <span className="studio-attempt">
216	          {mod.name}
217	          {mod.attempts.length ? ` · attempt ${mod.attempts.length}` : ""}
218	        </span>
219	      )}
220	    </div>
221	  );
222	}
223	
224	function Feed({ feed, mod }) {
225	  const ref = React.useRef(null);
226	  React.useEffect(() => {
227	    if (ref.current) ref.current.scrollTop = ref.current.scrollHeight;
228	  }, [feed.length]);
229	  const visible = feed.filter((f) => f.kind !== "result" || f.isError || f.role === "playtester");
230	  return (
231	    <section className="studio-feed" ref={ref}>
232	      {!visible.length && (
233	        <p className="studio-muted">
234	          {mod ? "Waiting for agent activity…" : "Agent activity appears here."}
235	        </p>
236	      )}
237	      {visible.slice(-250).map((f, i) => (
238	        <div key={`${f.at}-${i}`} className={`feed-row ${f.role} ${f.kind}`}>
239	          <span className="feed-role">{ROLE[f.role] || f.role}</span>
240	          {f.attempt ? <span className="feed-attempt">#{f.attempt}</span> : null}
241	          <span className="feed-text">
242	            {f.kind === "tool" ? (
243	              <>
244	                <code>{f.name}</code> {f.summary}
245	              </>
246	            ) : f.kind === "result" ? (
247	              <>
248	                <code>{f.name}</code> → {f.text.slice(0, 300)}
249	              </>
250	            ) : (
251	              f.text
252	            )}
253	          </span>
254	        </div>
255	      ))}
256	    </section>
257	  );
258	}
259	
260	function CheckIcon({ status }) {
261	  const map = { pass: "✓", fail: "✕", blocked: "!", pending: "·" };
262	  return <span className={`check-icon ${status}`}>{map[status] || "·"}</span>;
263	}
264	
265	function Inspector({ mod }) {
266	  const verdict = latestVerdict(mod);
267	  const byId = new Map((verdict?.checks || []).map((c) => [c.id, c]));
268	  const last = mod.attempts[mod.attempts.length - 1];
269	  return (
270	    <>
271	      <div className="insp-head">
272	        <h3>{mod.name}</h3>
273	        <span className={`pill ${mod.status}`}>{mod.status}</span>
274	      </div>
275	      {mod.seed && (
276	        <div className="insp-seed">
277	          Seeded bug fallback: attempt 1 uses a labeled buggy fixture.
278	        </div>
279	      )}
280	      <p className="insp-prompt">“{mod.prompt}”</p>
281	      {mod.running && (
282	        <button className="studio-stop" onClick={() => call("studio:stop", { id: mod.id })}>
283	          Stop
284	        </button>
285	      )}
286	      {mod.error && <div className="studio-error">{mod.error}</div>}
287	
288	      <h4>
289	        In-game test plan
290	        {verdict?.live && last?.status === "running" ? (
291	          <span className="live">live</span>
292	        ) : null}
293	      </h4>
294	      {!mod.testPlan && <p className="studio-muted">The spec agent is writing it…</p>}
295	      <ul className="insp-checks">
296	        {(mod.testPlan?.checks || []).map((c) => {
297	          const r = byId.get(c.id);
298	          return (
299	            <li key={c.id}>
300	              <CheckIcon status={r?.status || "pending"} />
301	              <div>
302	                <strong>{c.title}</strong>
303	                <small>{r?.observed || c.expect}</small>
304	              </div>
305	            </li>
306	          );
307	        })}
308	      </ul>
309	      {verdict?.serverErrors?.length > 0 && (
310	        <div className="studio-error">
311	          {verdict.serverErrors.length} server error(s):{" "}
312	          {verdict.serverErrors[0].message.slice(0, 160)}
313	        </div>
314	      )}
315	
316	      <h4>Attempts</h4>
317	      <ol className="insp-attempts">
318	        {mod.attempts.map((a) => (
319	          <Attempt key={a.n} attempt={a} />
320	        ))}
321	      </ol>
322	      {!mod.attempts.length && <p className="studio-muted">No attempts yet.</p>}
323	
324	      <h4>Partners</h4>
325	      <Partners mod={mod} />
326	    </>
327	  );
328	}
329	
330	function Attempt({ attempt }) {
331	  return (
332	    <li className={`attempt ${attempt.status}`}>
333	      <div className="attempt-head">
334	        <strong>
335	          #{attempt.n} {attempt.role === "seeded" ? "Seeded (labeled)" : ROLE[attempt.role]}
336	        </strong>
337	        <span className={`pill ${attempt.status}`}>{attempt.status}</span>
338	      </div>
339	      {attempt.failure && <p className="attempt-fail">{attempt.failure.summary}</p>}
340	      {attempt.lesson && <p className="attempt-lesson">Lesson: {attempt.lesson}</p>}
341	      {attempt.context && (
342	        <p className="attempt-meta">
343	          Fixer context: {attempt.context.entireCheckpoints} Entire checkpoints
344	          {attempt.context.neatlogsTrace ? ", Neatlogs trace" : ""}
345	        </p>
346	      )}
347	      <div className="attempt-meta">
348	        {attempt.commit?.sha && <code>{attempt.commit.sha.slice(0, 7)}</code>}
349	        {attempt.commit?.checkpoint && (
350	          <span className="tag entire" title="Entire checkpoint">
351	            Entire {attempt.commit.checkpoint.slice(0, 10)}
352	          </span>
353	        )}
354	        {attempt.playtestCommit?.checkpoint && (
355	          <span className="tag entire" title="Entire checkpoint for the playtest session">
356	            Entire {attempt.playtestCommit.checkpoint.slice(0, 10)}
357	          </span>
358	        )}
359	      </div>
360	      <div className="attempt-sessions">
361	        {attempt.sessions.map((s, i) => (
362	          <Session key={i} session={s} />
