2	import { call, on } from "../../api.js";
3	import "./game.css";
4	
5	const LABEL = {
6	  stopped: "Stopped",
7	  starting: "Starting",
8	  running: "Running",
9	  error: "Error",
10	  offline: "Offline",
11	  connecting: "Joining",
12	  online: "In game",
13	};
14	
15	// One-line summary of a bot tool call for the overlay.
16	function describe(a) {
17	  if (a.error) return a.error.slice(0, 80);
18	  const r = a.result;
19	  if (r?.after) return `${r.after.name} ↑ ${r.after.maxUpwardVelocity} b/t, +${r.after.maxHeightGain} blocks`;
20	  if (a.tool === "track_entity" && r) return `${r.name} ↑ ${r.maxUpwardVelocity} b/t, +${r.maxHeightGain} blocks`;
21	  if (a.tool === "nearby_entities" && Array.isArray(r)) return r.slice(0, 3).map((e) => `${e.name}#${e.id}`).join(" ") || "nothing nearby";
22	  if (a.tool === "game_setup") return (a.args?.commands || []).join(" · ").slice(0, 80);
23	  if (a.tool === "equip") return r?.holding || "";
24	  return JSON.stringify(a.args || {}).slice(0, 80);
25	}
26	
27	// Live view of the test bot inside the local Paper server. Owner: Track A.
28	export default function GamePane({ showLog = true }) {
29	  const [status, setStatus] = React.useState(null);
30	  const [busy, setBusy] = React.useState(false);
31	  const [error, setError] = React.useState("");
32	  const [lines, setLines] = React.useState([]);
33	  const [actions, setActions] = React.useState([]);
34	  const [demo, setDemo] = React.useState(false);
35	
36	  React.useEffect(() => {
37	    call("game:status").then(setStatus).catch((e) => setError(e.message));
38	    const offs = [
39	      on("game:status", setStatus),
40	      on("game:log", (l) => setLines((prev) => [...prev.slice(-199), l])),
41	      on("game:action", (a) => setActions((prev) => [...prev.slice(-29), a])),
42	    ];
43	    return () => offs.forEach((off) => off());
44	  }, []);
45	
46	  const toggle = async () => {
47	    setBusy(true);
48	    setError("");
49	    try {
50	      setStatus(await call(running ? "game:stop" : "game:start"));
51	    } catch (e) {
52	      setError(e.message);
53	    } finally {
54	      setBusy(false);
55	    }
56	  };
57	
58	  const running = status && status.server !== "stopped";
59	  const recent = actions.filter((a) => a.done).slice(-3);
60	
61	  return (
62	    <section className="game-pane">
63	      <header className="game-bar">
64	        <strong>Minecraft {status?.version || ""}</strong>
65	        <span className={`game-dot ${status?.server || "stopped"}`} />
66	        <span>Server: {LABEL[status?.server] || "Unknown"}</span>
67	        <span className={`game-dot ${status?.bot || "offline"}`} />
68	        <span>Bot: {LABEL[status?.bot] || "Unknown"}</span>
69	        {status?.mock && <span className="game-tag">Mock runtime</span>}
70	        {status?.bot === "online" && (
71	          <button
72	            className="game-btn ghost"
73	            onClick={() =>
74	              call("game:demo", { on: !demo })
75	                .then((r) => setDemo(r.demo))
76	                .catch((e) => setError(e.message))
77	            }
78	          >
79	            {demo ? "Stop demo" : "Demo hits"}
80	          </button>
81	        )}
82	        <button className="game-btn" disabled={busy} onClick={toggle}>
83	          {busy ? "Working…" : running ? "Stop" : "Start game"}
84	        </button>
85	      </header>
86	      <div className="game-view">
87	        {status?.viewerUrl ? (
88	          <iframe title="Bot view" src={status.viewerUrl} />
89	        ) : (
90	          <div className="game-empty">
91	            {status?.server === "starting"
92	              ? "Starting the Paper server…"
93	              : "Start the game to watch the AI player."}
94	          </div>
