.game-pane {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  gap: 10px;
}
.game-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #949ba3;
}
.game-bar strong {
  margin-right: 8px;
  font-family: Bahnschrift, "Segoe UI Semibold", system-ui, sans-serif;
  font-weight: 600;
  color: #ece9e2;
}
.game-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #626a72;
}
.game-dot.starting,
.game-dot.connecting {
  background: #f2b544;
}
.game-dot.running,
.game-dot.online {
  background: #7fcf5a;
}
.game-dot.error {
  background: #ec6a5b;
}
.game-tag {
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(242, 181, 68, 0.14);
  color: #f2b544;
  font-size: 10.5px;
  font-weight: 600;
}
.game-btn {
  margin-left: auto;
  padding: 7px 14px;
  border: 0;
  border-radius: 9px;
  background: #f2b544;
  color: #1a1408;
  font-weight: 600;
  cursor: pointer;
}
.game-btn.ghost {
  background: #1d2226;
  border: 1px solid #373f46;
  color: #ece9e2;
  font-weight: 500;
}
.game-btn.ghost + .game-btn {
  margin-left: 0;
}
.game-btn:hover:not(:disabled) {
  filter: brightness(1.08);
}
.game-btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.game-view {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 1px solid #2a3035;
  border-radius: 12px;
  overflow: hidden;
  background: #0b0d0f;
}
.game-view iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
.game-empty {
  display: grid;
  place-items: center;
  height: 100%;
  color: #626a72;
  font-size: 13px;
}
.game-actions {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.game-action.error code {
  color: #f5a196;
}
.game-action {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 6px 10px;
  border-radius: 7px;
  background: rgba(12, 14, 16, 0.85);
  border: 1px solid #2a3035;
  color: #ece9e2;
  font-size: 12px;
