function Stat({ label, value, sub }) {
  return (
    <div className="kpi">
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{sub}</small>
    </div>
  );
}

const SERIES = [
  ["passed", "Passed"],
  ["failed", "Failed"],
  ["running", "Running"],
];

function DailyBars({ days }) {
  const [hover, setHover] = React.useState(null);
  const W = 760;
  const H = 168;
  const max = Math.max(1, ...days.map((d) => d.passed + d.failed + d.running));
  const slot = W / days.length;
  const bar = Math.min(28, slot * 0.5);
  const gap = 2;
  const ticks = max <= 4 ? Array.from({ length: max }, (_, i) => i + 1) : [Math.round(max / 2), max];
  const hovered = hover == null ? null : days[hover];

  return (
    <div className="chart">
      <svg className="daily" viewBox={`0 0 ${W} ${H + 24}`} role="img" aria-label="Mods per day by outcome">
        <line x1="0" x2={W} y1={H} y2={H} className="axis" />
        {ticks.map((t) => (
          <g key={t}>
            <line x1="0" x2={W} y1={H - (t / max) * H} y2={H - (t / max) * H} className="grid" />
            <text x="0" y={H - (t / max) * H - 5} className="tick">
              {t}
            </text>
          </g>
        ))}
        {days.map((d, i) => {
          const x = i * slot + (slot - bar) / 2;
          const segs = SERIES.map(([k]) => [k, d[k]]).filter(([, n]) => n);
          let y = H;
          return (
            <g key={d.key} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
              <rect className="hit" x={i * slot} y="0" width={slot} height={H + 24} />
              {hover === i && <rect className="hover-band" x={i * slot + 2} y="0" width={slot - 4} height={H} rx="4" />}
              {segs.map(([kind, n], j) => {
                const h = Math.max(2, (n / max) * H - (j > 0 ? gap : 0));
                y -= h + (j > 0 ? gap : 0);
                const top = j === segs.length - 1;
                return top ? (
                  <path key={kind} className={kind} d={roundedTop(x, y, bar, h, 4)} />
                ) : (
                  <rect key={kind} className={kind} x={x} y={y} width={bar} height={h} />
                );
              })}
              {(i % 2 === 1 || i === days.length - 1) && (
                <text x={x + bar / 2} y={H + 17} textAnchor="middle" className="tick">
                  {label(d.key)}
                </text>
              )}
            </g>
          );
        })}
      </svg>
      {hovered && (
        <div className="tooltip" style={{ left: `${((hover + 0.5) / days.length) * 100}%` }}>
          <strong>{label(hovered.key)}</strong>
          {SERIES.map(([k, name]) => (
            <span key={k}>
              <i className={k} />
              {name}
              <b>{hovered[k]}</b>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

const label = (key) => {
  const [, m, d] = key.split("-");
  return new Date(2000, Number(m) - 1, Number(d)).toLocaleDateString([], { month: "short", day: "numeric" });
};

function roundedTop(x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h);
  return `M${x},${y + h}V${y + rr}Q${x},${y} ${x + rr},${y}H${x + w - rr}Q${x + w},${y} ${x + w},${y + rr}V${y + h}Z`;
}

function Bars({ rows, empty }) {
  const max = Math.max(1, ...rows.map(([, n]) => n));
  const total = rows.reduce((n, [, v]) => n + v, 0);
  if (!total) return <Empty>{empty}</Empty>;
  return (
    <ul className="hbars">
      {rows.map(([name, n]) => (
        <li key={name}>
          <span>{name}</span>
          <span className="meter">
            <i style={{ width: `${(n / max) * 100}%` }} />
          </span>
          <strong>{n}</strong>
        </li>
      ))}
    </ul>
  );
}

function Coverage({ label: name, value, sub, tone }) {
  return (
    <div className="coverage">
      <span className={`partner-dot ${tone}`} />
      <div>
        <strong>{value}</strong>
        <span>{name}</span>
        <small>{sub}</small>
      </div>
    </div>
  );
}

