  grid-template-columns: 228px minmax(480px, 1fr) 330px;
  background: #fff;
  overflow: hidden;
}
.sidebar {
  background: #f5f4f0;
  border-right: 1px solid #e4e2dc;
  padding: 12px 10px 10px;
  display: flex;
  border: 1px solid #dcd8d0;
  border-radius: 7px;
  background: #f6f4f0;
  padding: 0 10px;
}
button:focus-visible,
a:focus-visible,
textarea:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 2px solid #7765d2;
  outline-offset: 2px;
}
@media (max-width: 1100px) {
