/* Mod Studio: calm dark workbench. One accent (banana) for live state; status by dot + label. */

.studio {
  --bg: #0b0c0e;
  --side: #0e0f12;
  --panel: #121317;
  --raised: #17191d;
  --hover: #1c1e23;
  --line: rgba(255, 255, 255, 0.07);
  --line-strong: rgba(255, 255, 255, 0.12);
  --text: #ececef;
  --text-2: #a3a6ae;
  --text-3: #6e727c;
  --accent: #f5c84c;
  --accent-soft: rgba(245, 200, 76, 0.12);
  --good: #4cc38a;
  --good-text: #74d6a6;
  --good-soft: rgba(76, 195, 138, 0.12);
  --warn: #f0b429;
  --bad: #e5484d;
  --bad-text: #f2777b;
  --bad-soft: rgba(229, 72, 77, 0.1);
  --neatlogs: #4fb8d0;
  --entire: #a78bfa;
  --sans: "Segoe UI Variable Text", "Segoe UI", Inter, system-ui, sans-serif;
  --display: "Segoe UI Variable Display", "Segoe UI", Inter, system-ui, sans-serif;
  --mono: "Cascadia Code", "JetBrains Mono", Consolas, monospace;

  display: grid;
  grid-template-columns: 236px minmax(0, 1fr);
  height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
.studio *,
.studio *::before,
.studio *::after {
  box-sizing: border-box;
}
.studio button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.studio button:disabled {
  cursor: default;
}
.studio :focus-visible {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio h1,
.studio h2,
.studio h3,
.studio p {
  margin: 0;
}
.studio ::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.studio ::-webkit-scrollbar-track {
  background: transparent;
}
.studio ::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09) padding-box;
}
.studio ::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.18) padding-box;
}
.studio ::-webkit-scrollbar-corner {
  background: transparent;
}

/* ---------- Shared primitives ---------- */

.studio .ico {
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.studio .meta {
  color: var(--text-3);
  font-size: 12px;
}
.studio .muted {
  color: var(--text-3);
}
.studio .mono {
  font-family: var(--mono);
  font-size: 12px;
}
.studio .strong {
  color: var(--text);
  font-weight: 500;
}
.studio .empty {
  padding: 14px 0;
  color: var(--text-3);
  font-size: 12.5px;
}
.studio .alert {
  padding: 9px 12px;
  border: 1px solid rgba(229, 72, 77, 0.28);
  border-radius: 8px;
  background: var(--bad-soft);
  color: var(--bad-text);
  font-size: 12.5px;
}
.studio .page-alert {
  margin: 16px 32px 0;
}
.studio .tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .link:hover {
  color: var(--text);
}

.studio .btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition: background 0.12s, border-color 0.12s;
}
.studio .btn:hover:not(:disabled) {
  background: var(--hover);
  border-color: rgba(255, 255, 255, 0.18);
}
.studio .btn:disabled {
  opacity: 0.45;
}
.studio .btn.solid {
  border-color: transparent;
  background: var(--text);
  color: #0b0c0e;
  font-weight: 600;
}
.studio .btn.solid:hover:not(:disabled) {
  background: #fff;
}
.studio .btn.danger {
  border-color: rgba(229, 72, 77, 0.35);
  background: var(--bad-soft);
  color: var(--bad-text);
}
.studio .btn.danger:hover:not(:disabled) {
  background: rgba(229, 72, 77, 0.16);
  border-color: rgba(229, 72, 77, 0.5);
}
.studio .btn kbd {
  margin-left: 2px;
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 500;
  opacity: 0.5;
}

.studio .dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .dot.passed {
  background: var(--good);
}
.studio .dot.failed {
  background: var(--bad);
}
.studio .dot.running,
.studio .dot.queued {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .dot.stopped,
.studio .dot.idle {
  background: transparent;
  border: 1.5px solid var(--text-3);
}

.studio .status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .status.passed,
.studio .status.pass {
  color: var(--good-text);
}
.studio .status.passed i,
.studio .status.pass i {
  background: var(--good);
}
.studio .status.failed,
.studio .status.fail {
  color: var(--bad-text);
}
.studio .status.failed i,
.studio .status.fail i {
  background: var(--bad);
}
.studio .status.running,
.studio .status.queued {
  color: var(--accent);
}
.studio .status.running i,
.studio .status.queued i {
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(245, 200, 76, 0.45);
  }
  50% {
    box-shadow: 0 0 0 4px rgba(245, 200, 76, 0);
  }
}

.studio .check-icon {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  color: var(--text-3);
}
.studio .check-icon .ico {
  stroke-width: 2.2;
}
.studio .check-icon.pass {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .check-icon.fail {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .check-icon.blocked {
  border-color: transparent;
  background: rgba(240, 180, 41, 0.12);
  color: var(--warn);
}
.studio .check-icon.running {
  border-color: var(--accent);
  border-right-color: transparent;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.studio .panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .panel.pad {
  padding: 18px 20px;
}
.studio .panel-head {
  padding: 14px 16px 4px;
}

.studio .section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 24px;
  margin-bottom: 8px;
}
.studio .section-head h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.studio .count {
  padding: 0 6px;
  border-radius: 99px;
  background: var(--raised);
  color: var(--text-3);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.studio .block + .block {
  margin-top: 26px;
}

.studio .segmented {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--line);
}
.studio .segmented button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .segmented button:hover {
  color: var(--text);
}
.studio .segmented button.on {
  background: var(--raised);
  color: var(--text);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 1px 2px rgba(0, 0, 0, 0.4);
}
.studio .segmented span {
  color: var(--text-3);
  font-size: 11px;
}

.studio .tabs {
  display: flex;
  gap: 20px;
  margin-top: 18px;
  border-bottom: 1px solid var(--line);
}
.studio .tabs button {
  position: relative;
  height: 36px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 13px;
  font-weight: 500;
}
.studio .tabs button:hover {
  color: var(--text-2);
}
.studio .tabs button.on {
  color: var(--text);
}
.studio .tabs button.on::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  border-radius: 2px;
  background: var(--text);
}

.studio .table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}
.studio .table th {
  padding: 0 12px 9px;
  border-bottom: 1px solid var(--line);
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
  text-align: left;
  white-space: nowrap;
}
.studio .table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  vertical-align: middle;
}
.studio .table th:first-child,
.studio .table td:first-child {
  padding-left: 0;
}
.studio .table th:last-child,
.studio .table td:last-child {
  padding-right: 0;
}
.studio .table tr:last-child td {
  border-bottom: 0;
}
.studio .table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .panel > .table th:first-child,
.studio .panel > .table td:first-child {
  padding-left: 18px;
}
.studio .panel > .table th:last-child,
.studio .panel > .table td:last-child {
  padding-right: 18px;
}
.studio .panel > .table th {
  padding-top: 14px;
}
.studio .table.selectable tbody tr {
  cursor: pointer;
}
.studio .table.selectable tbody tr:hover td {
  background: rgba(255, 255, 255, 0.02);
}
.studio .table.selectable tbody tr.selected td {
  background: rgba(255, 255, 255, 0.045);
}

.studio .meter {
  display: block;
  width: 100%;
  min-width: 60px;
  height: 6px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.studio .meter i {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: var(--text-2);
}

.studio .facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 18px 0 0;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .facts > div {
  padding: 10px 14px;
}
.studio .facts > div + div {
  border-left: 1px solid var(--line);
}
.studio .facts dt {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .facts dd {
  margin: 2px 0 0;
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .facts.stacked {
  grid-template-columns: 1fr;
  margin: 14px 0;
}
.studio .facts.stacked > div + div {
  border-left: 0;
  border-top: 1px solid var(--line);
}
.studio .facts.stacked dd {
  font-size: 12.5px;
  font-weight: 500;
  word-break: break-all;
}

/* ---------- Shell ---------- */

.studio .side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 14px 10px 10px;
  border-right: 1px solid var(--line);
  background: var(--side);
}
.studio .logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 2px 8px 14px;
}
.studio .logo strong {
  display: block;
  font-family: var(--display);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
}
.studio .logo small {
  display: block;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .brand-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--accent);
  color: #1b1503;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
}
.studio .new-mod {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  margin: 0 0 14px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}
.studio .new-mod:hover {
  background: var(--hover);
}
.studio .nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.studio .nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .nav-item svg {
  width: 17px;
  height: 17px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.85;
}
.studio .nav-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .nav-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
  font-weight: 500;
}
.studio .live-dot {
  width: 6px;
  height: 6px;
  margin-left: auto;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
.studio .side-section {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  margin-top: 22px;
}
.studio .side-label {
  display: block;
  padding: 0 10px 6px;
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
}
.studio .recents {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.studio .recent-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  height: 30px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
  text-align: left;
}
.studio .recent-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .recent-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
}
.studio .recent-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .recent-item small {
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.studio .side-empty {
  padding: 4px 10px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .side-foot {
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.studio .runtime-status {
  display: grid;
  gap: 6px;
  padding: 4px 10px 10px;
}
.studio .runtime-status > div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .runtime-status small {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .runtime-status .dot.passed {
  box-shadow: 0 0 0 3px var(--good-soft);
}
.studio .mock-note {
  justify-self: start;
  margin-top: 2px;
  padding: 0 7px;
  border: 1px dashed var(--line-strong);
  border-radius: 99px;
  color: var(--text-3);
  font-size: 11px;
  line-height: 18px;
}

.studio-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.studio .view {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 18px;
  min-height: 0;
  padding: 26px 32px 40px;
  overflow-y: auto;
}
.studio .view.fill {
  overflow: hidden;
  padding-bottom: 24px;
}
.studio .page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}
.studio .page-head h1 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .page-head p {
  margin-top: 3px;
  color: var(--text-2);
}
.studio .page-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
}

/* ---------- Partners ---------- */

.studio .partner-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-dot.entire {
  background: var(--entire);
}
.studio .partner-dot.neatlogs {
  background: var(--neatlogs);
}
.studio .partner-dot.off {
  background: transparent;
  border: 1.5px solid var(--text-3);
}
.studio .partner-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio button.partner-link:hover {
  border-color: var(--line-strong);
  color: var(--text);
}
.studio .partner-link i {
  width: 6px;
  height: 6px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-link.neatlogs i {
  background: var(--neatlogs);
}
.studio .partner-link.entire i {
  background: var(--entire);
}
.studio .partner-link.off i {
  background: transparent;
  border: 1px solid var(--text-3);
}
.studio .partner-link.static {
  font-family: var(--mono);
  font-size: 11px;
}
.studio .partners {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .partners li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12.5px;
}
.studio .partners strong {
  font-weight: 500;
}
.studio .partners .meta {
  margin-left: auto;
}

/* ---------- Test plan and attempts ---------- */

.studio .check-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .check-list li {
  display: flex;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .check-list li:first-child {
  border-top: 0;
}
.studio .check-list strong {
  display: block;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  line-height: 18px;
}
.studio .check-list p {
  margin-top: 3px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .check-list li.fail p {
  color: var(--text-2);
}

.studio .attempts {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .attempt {
  position: relative;
  padding-bottom: 18px;
}
.studio .attempt:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 22px;
  bottom: 2px;
  left: 8.5px;
  width: 1px;
  background: var(--line-strong);
}
.studio .attempt-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 20px;
}
.studio .attempt-head strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .attempt-head .status {
  margin-left: auto;
}
.studio .attempt-body {
  display: grid;
  gap: 10px;
  padding: 8px 0 0 28px;
}
.studio .attempt-text {
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .lesson {
  padding: 9px 12px;
  border-left: 2px solid var(--good);
  border-radius: 0 6px 6px 0;
  background: var(--good-soft);
}
.studio .lesson span {
  display: block;
  margin-bottom: 2px;
  color: var(--good-text);
  font-size: 11.5px;
  font-weight: 600;
}
.studio .lesson p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .attempt-refs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.studio .sha {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio button.sha:hover:not(:disabled) {
  border-color: var(--line-strong);
}
.studio .sha.static,
.studio button.sha:disabled {
  opacity: 1;
}
.studio .sessions {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .sessions li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  min-width: 0;
  padding: 7px 10px;
}
.studio .sessions li + li {
  border-top: 1px solid var(--line);
}
.studio .session-role {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 500;
}
.studio .sessions .meta {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Build: composer ---------- */

.studio .compose-page {
  align-items: center;
}
.studio .compose {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
  max-width: 720px;
  padding-top: 7vh;
}
.studio .compose h1 {
  font-family: var(--display);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.studio .lede {
  max-width: 600px;
  margin-top: -8px !important;
  color: var(--text-2);
  font-size: 14px;
}
.studio .running-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
  border: 1px solid rgba(245, 200, 76, 0.25);
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--text-2);
  text-align: left;
}
.studio .running-banner strong {
  color: var(--text);
  font-weight: 600;
}
.studio .banner-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: var(--text);
  font-weight: 500;
}
.studio .prompt-box {
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 12px 32px -16px rgba(0, 0, 0, 0.6);
  transition: border-color 0.15s;
}
.studio .prompt-box:focus-within {
  border-color: rgba(255, 255, 255, 0.24);
}
.studio .prompt-box textarea {
  display: block;
  width: 100%;
  min-height: 112px;
  padding: 16px 18px 8px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 15px;
  line-height: 1.55;
  resize: none;
}
.studio .prompt-box textarea::placeholder {
  color: var(--text-3);
}
.studio .prompt-box.seeded textarea {
  opacity: 0.4;
}
.studio .composer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 10px 10px 16px;
}
.studio .toggle {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12.5px;
  cursor: pointer;
  user-select: none;
}
.studio .toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.studio .switch {
  position: relative;
  width: 28px;
  height: 16px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.15s;
}
.studio .switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text);
  transition: transform 0.15s;
}
.studio .toggle input:checked + .switch {
  background: var(--accent);
}
.studio .toggle input:checked + .switch::after {
  transform: translateX(12px);
  background: #1b1503;
}
.studio .toggle input:focus-visible + .switch {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio .examples {
  display: grid;
  gap: 2px;
}
.studio .examples .side-label {
  padding: 4px 0 6px;
}
.studio .examples button {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  margin: 0 -12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .examples button span {
  flex: 1;
}
.studio .examples button .ico {
  opacity: 0;
  transition: opacity 0.12s, transform 0.12s;
}
.studio .examples button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .examples button:hover:not(:disabled) .ico {
  opacity: 1;
  transform: translateX(2px);
}
.studio .examples button:disabled {
  opacity: 0.4;
}
.studio .flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 12px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  list-style: none;
  gap: 18px;
}
.studio .flow li {
  display: grid;
  gap: 4px;
}
.studio .flow-n {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-bottom: 4px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  color: var(--text-3);
  font-size: 11px;
  font-weight: 600;
}
.studio .flow strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .flow p {
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
}
.studio .lessons {
  margin-top: 8px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .lessons .section-head {
  margin-bottom: 0;
}
.studio .lessons ul,
.studio .lesson-list {
  display: grid;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .lessons li,
.studio .lesson-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .lessons li p,
.studio .lesson-list li p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .lessons li small,
.studio .lesson-list li small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Build: run view ---------- */

.studio .run-page {
  gap: 16px;
  padding: 22px 28px 22px;
  overflow: hidden;
}
.studio .run-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
.studio .run-title {
  min-width: 0;
}
.studio .run-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}
.studio .run-name h1,
.studio .run-name h2 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .run-name h2 {
  font-size: 19px;
}
.studio .run-title p,
.studio .detail-title p {
  max-width: 820px;
  margin-top: 4px;
  overflow: hidden;
  color: var(--text-2);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.studio .pipeline {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  list-style: none;
}
.studio .pipeline li {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--text-3);
  font-size: 12.5px;
  white-space: nowrap;
}
.studio .pipeline li::after {
  content: "";
  flex: 1;
  height: 1px;
  min-width: 8px;
  margin: 0 10px;
  background: var(--line-strong);
}
.studio .pipeline li:nth-last-child(2) {
  flex: none;
}
.studio .pipeline li:nth-last-child(2)::after,
.studio .pipeline .pipe-meta::after {
  display: none;
}
.studio .pipe-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
}
.studio .pipe-icon .ico {
  stroke-width: 2.4;
}
.studio .pipeline li.done {
  color: var(--text-2);
}
.studio .pipeline li.done::after {
  background: rgba(76, 195, 138, 0.4);
}
.studio .pipeline li.done .pipe-icon {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .pipeline li.current {
  color: var(--text);
  font-weight: 600;
}
.studio .pipeline li.current .pipe-icon {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .pipeline li.current .pipe-icon::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}
.studio .pipeline li.failed {
  color: var(--bad-text);
  font-weight: 600;
}
.studio .pipeline li.failed .pipe-icon {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .pipeline .pipe-meta {
  flex: none;
  margin-left: 18px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
  color: var(--text-2);
  font-weight: 500;
}

.studio .run-grid {
  display: grid;
  flex: 1;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 16px;
  min-height: 0;
}
.studio .run-stage {
  display: grid;
  grid-template-rows: minmax(0, 3fr) minmax(170px, 2fr);
  gap: 16px;
  min-height: 0;
}
.studio .run-side {
  min-height: 0;
  padding: 16px 18px 20px;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}

.studio .activity {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  overflow: hidden;
}
.studio .activity-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
}
.studio .activity-head h3 {
  font-size: 13px;
  font-weight: 600;
}
.studio .activity-body {
  flex: 1;
  min-height: 0;
  padding: 6px 0;
  overflow-y: auto;
}
.studio .activity-body .empty {
  padding: 14px;
}
.studio .event {
  display: grid;
  grid-template-columns: 62px 96px minmax(0, 1fr);
  gap: 10px;
  padding: 4px 14px;
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .event:hover {
  background: rgba(255, 255, 255, 0.02);
}
.studio .event time {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11px;
  line-height: 20px;
}
.studio .event-role {
  display: flex;
  align-items: baseline;
  gap: 4px;
  overflow: hidden;
  color: var(--text-3);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .event-role small {
  color: var(--text-3);
  font-size: 11px;
  font-weight: 400;
}
.studio .event-role.playtester {
  color: #8fc7f5;
}
.studio .event-role.builder {
  color: #c7b4fa;
}
.studio .event-role.fixer {
  color: #f5b98f;
}
.studio .event-role.spec {
  color: #a8dcc2;
}
.studio .event-role.benana {
  color: var(--accent);
}
.studio .event-text {
  min-width: 0;
  color: var(--text-2);
  overflow-wrap: anywhere;
}
.studio .event-text code {
  margin-right: 8px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event-text .result {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event.text .event-text,
.studio .event.phase .event-text {
  color: var(--text);
}
.studio .event.failure .event-text,
.studio .event.error .event-text {
  color: var(--bad-text);
}

/* ---------- Mods ---------- */

.studio .mods {
  display: grid;
  flex: 1;
  grid-template-columns: 340px minmax(0, 1fr);
  gap: 16px;
  min-height: 0;
}
.studio .mods-list {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 12px;
}
.studio .mods-list .segmented {
  align-self: flex-start;
  margin-bottom: 10px;
}
.studio .list {
  display: grid;
  align-content: start;
  gap: 1px;
  min-height: 0;
  overflow-y: auto;
}
.studio .list-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  text-align: left;
}
.studio .list-row:hover {
  background: rgba(255, 255, 255, 0.035);
}
.studio .list-row.active {
  background: rgba(255, 255, 255, 0.07);
}
.studio .list-main {
  flex: 1;
  min-width: 0;
}
.studio .list-main strong {
  display: block;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .list-main small {
  color: var(--text-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}
.studio .entire-split .list {
  padding: 0 8px 8px;
}
.studio .mods-detail {
  min-height: 0;
  padding: 20px 24px 28px;
  overflow-y: auto;
}
.studio .detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}
.studio .detail-title {
  min-width: 0;
}
.studio .overview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 36px;
  padding-top: 22px;
}
.studio .overview-col {
  min-width: 0;
}
.studio .prose {
  color: var(--text-2);
  line-height: 1.6;
}
.studio .bullets {
  margin: 10px 0 0;
  padding-left: 18px;
  color: var(--text-2);
}
.studio .bullets li {
  padding: 2px 0;
}
.studio .bullets li::marker {
  color: var(--text-3);
}

/* ---------- Code ---------- */

.studio .code {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 18px;
}
.studio .code .segmented {
  align-self: flex-start;
}
.studio .code-split {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: 420px;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.studio .file-tree {
  padding: 10px 8px;
  border-right: 1px solid var(--line);
  background: var(--bg);
  overflow-y: auto;
}
.studio .tree-group + .tree-group {
  margin-top: 10px;
}
.studio .tree-group small {
  display: block;
  padding: 2px 8px 4px;
  overflow: hidden;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button {
  display: block;
  width: 100%;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .file-tree button.on {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
}
.studio .commit-list button {
  display: grid;
  gap: 1px;
  font-family: var(--sans);
  font-size: 12.5px;
}
.studio .commit-list small {
  color: var(--text-3);
  font-size: 11px;
}
.studio .viewer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #0d0e11;
}
.studio .viewer-head {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  font-size: 11.5px;
}
.studio .code-body {
  flex: 1;
  max-height: 62vh;
  padding: 8px 0;
  overflow: auto;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.65;
}
.studio .code-line {
  display: flex;
  min-width: max-content;
  padding-right: 16px;
}
.studio .code-line .ln {
  flex: none;
  width: 48px;
  padding-right: 14px;
  color: #4b4f58;
  text-align: right;
  user-select: none;
}
.studio .code-line .lc {
  color: #d4d6dc;
  white-space: pre;
}
.studio .code-line:not(:has(.ln)) .lc {
  padding-left: 16px;
}
.studio .code-line.add {
  background: rgba(76, 195, 138, 0.09);
}
.studio .code-line.add .lc {
  color: #9be0bd;
}
.studio .code-line.del {
  background: rgba(229, 72, 77, 0.09);
}
.studio .code-line.del .lc {
  color: #f5a3a6;
}
.studio .code-line.hunk .lc {
  color: #8fc7f5;
}
.studio .code-line.meta .lc {
  color: var(--text-3);
}

/* ---------- Insights ---------- */

.studio .kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .kpis.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.studio .kpi {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 16px 20px;
}
.studio .kpi + .kpi {
  border-left: 1px solid var(--line);
}
.studio .kpi span {
  color: var(--text-2);
  font-size: 12px;
}
.studio .kpi strong {
  margin-top: 4px;
  color: var(--text);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.studio .kpi small {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .legend {
  display: flex;
  gap: 16px;
}
.studio .lg {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .lg::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .lg.passed::before {
  background: var(--good);
}
.studio .lg.failed::before {
  background: var(--bad);
}
.studio .lg.running::before {
  background: var(--accent);
}
.studio .chart {
  position: relative;
  margin-top: 14px;
}
.studio .daily {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.studio .daily .axis {
  stroke: var(--line-strong);
}
.studio .daily .grid {
  stroke: var(--line);
  stroke-dasharray: 2 4;
}
.studio .daily .tick {
  fill: var(--text-3);
  font-size: 11px;
}
.studio .daily .hit {
  fill: transparent;
}
.studio .daily .hover-band {
  fill: rgba(255, 255, 255, 0.04);
}
.studio .daily .passed {
  fill: var(--good);
}
.studio .daily .failed {
  fill: var(--bad);
}
.studio .daily .running {
  fill: var(--accent);
}
.studio .tooltip {
  position: absolute;
  top: 0;
  z-index: 2;
  display: grid;
  gap: 3px;
  min-width: 140px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #1a1c21;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  pointer-events: none;
  transform: translate(-50%, -8px);
}
.studio .tooltip strong {
  margin-bottom: 2px;
  font-weight: 600;
}
.studio .tooltip span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
}
.studio .tooltip i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .tooltip i.passed {
  background: var(--good);
}
.studio .tooltip i.failed {
  background: var(--bad);
}
.studio .tooltip i.running {
  background: var(--accent);
}
.studio .tooltip b {
  margin-left: auto;
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .insight-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.studio .insight-grid .section-head ~ .section-head {
  margin-top: 22px;
}
.studio .hbars {
  display: grid;
  gap: 10px;
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}
.studio .hbars li {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 12px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .hbars strong {
  color: var(--text);
  font-weight: 600;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .coverage-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.studio .coverage {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .coverage .partner-dot {
  margin-top: 6px;
}
.studio .coverage strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.studio .coverage span {
  display: block;
  color: var(--text);
  font-size: 12.5px;
}
.studio .coverage small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Neatlogs and Entire ---------- */

.studio .connection {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .connection strong {
  flex: none;
  font-weight: 600;
}
.studio .connection .meta {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  align-items: start;
  gap: 16px;
}
.studio .split > .panel:first-child {
  overflow-x: auto;
}
.studio .entire-split {
  grid-template-columns: 300px minmax(0, 1fr);
}
.studio .detail-card {
  position: sticky;
  top: 0;
}
.studio .trace {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .trace-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.studio .trace-head strong {
  font-weight: 600;
}
.studio .spans {
  display: grid;
  gap: 1px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .spans li {
  display: grid;
  padding: 5px 0 5px 12px;
  border-left: 2px solid rgba(79, 184, 208, 0.5);
  color: var(--text-2);
  font-size: 12px;
}
.studio .spans li.failed {
  border-left-color: var(--bad);
  color: var(--bad-text);
}
.studio .spans small {
  color: var(--text-3);
}
.studio .commits {
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .commits li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
}
.studio .commits li:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 26px;
  bottom: -10px;
  left: 4px;
  width: 1px;
  background: var(--line-strong);
}
.studio .commit-node {
  flex: none;
  width: 9px;
  height: 9px;
  border: 2px solid var(--good);
  border-radius: 50%;
  background: var(--panel);
}
.studio .commits li.bad .commit-node {
  border-color: var(--bad);
}
.studio .commit-main {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}
.studio .commit-main strong {
  font-weight: 500;
}

@media (max-width: 1360px) {
  .studio .run-grid {
    grid-template-columns: minmax(0, 1fr) 340px;
  }
  .studio .kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .studio .kpi:nth-child(4) {
    border-left: 0;
  }
  .studio .kpi:nth-child(n + 4) {
    border-top: 1px solid var(--line);
  }
  .studio .pipeline li > span:last-child {
    display: none;
  }
  .studio .pipeline li.current > span:last-child,
  .studio .pipeline li.failed > span:last-child,
  .studio .pipeline .pipe-meta {
    display: inline;
  }
}
@media (max-width: 1180px) {
  .studio {
    grid-template-columns: 200px minmax(0, 1fr);
  }
  .studio .insight-grid,
  .studio .overview,
  .studio .split,
  .studio .entire-split {
    grid-template-columns: 1fr;
  }
  .studio .mods {
    grid-template-columns: 280px minmax(0, 1fr);
  }
  .studio .flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

toolu_018FQkFiCxgJpGjdCzQSpqrw.content:
/* Mod Studio: calm dark workbench. One accent (banana) for live state; status by dot + label. */

.studio {
  --bg: #0b0c0e;
  --side: #0e0f12;
  --panel: #121317;
  --raised: #17191d;
  --hover: #1c1e23;
  --line: rgba(255, 255, 255, 0.07);
  --line-strong: rgba(255, 255, 255, 0.12);
  --text: #ececef;
  --text-2: #a3a6ae;
  --text-3: #6e727c;
  --accent: #f5c84c;
  --accent-soft: rgba(245, 200, 76, 0.12);
  --good: #4cc38a;
  --good-text: #74d6a6;
  --good-soft: rgba(76, 195, 138, 0.12);
  --warn: #f0b429;
  --bad: #e5484d;
  --bad-text: #f2777b;
  --bad-soft: rgba(229, 72, 77, 0.1);
  --neatlogs: #4fb8d0;
  --entire: #a78bfa;
  --sans: "Segoe UI Variable Text", "Segoe UI", Inter, system-ui, sans-serif;
  --display: "Segoe UI Variable Display", "Segoe UI", Inter, system-ui, sans-serif;
  --mono: "Cascadia Code", "JetBrains Mono", Consolas, monospace;

  display: grid;
  grid-template-columns: 236px minmax(0, 1fr);
  height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
.studio *,
.studio *::before,
.studio *::after {
  box-sizing: border-box;
}
.studio button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.studio button:disabled {
  cursor: default;
}
.studio :focus-visible {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio h1,
.studio h2,
.studio h3,
.studio p {
  margin: 0;
}
.studio ::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.studio ::-webkit-scrollbar-track {
  background: transparent;
}
.studio ::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09) padding-box;
}
.studio ::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.18) padding-box;
}
.studio ::-webkit-scrollbar-corner {
  background: transparent;
}

/* ---------- Shared primitives ---------- */

.studio .ico {
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.studio .meta {
  color: var(--text-3);
  font-size: 12px;
}
.studio .muted {
  color: var(--text-3);
}
.studio .mono {
  font-family: var(--mono);
  font-size: 12px;
}
.studio .strong {
  color: var(--text);
  font-weight: 500;
}
.studio .empty {
  padding: 14px 0;
  color: var(--text-3);
  font-size: 12.5px;
}
.studio .alert {
  padding: 9px 12px;
  border: 1px solid rgba(229, 72, 77, 0.28);
  border-radius: 8px;
  background: var(--bad-soft);
  color: var(--bad-text);
  font-size: 12.5px;
}
.studio .page-alert {
  margin: 16px 32px 0;
}
.studio .tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .link:hover {
  color: var(--text);
}

.studio .btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition: background 0.12s, border-color 0.12s;
}
.studio .btn:hover:not(:disabled) {
  background: var(--hover);
  border-color: rgba(255, 255, 255, 0.18);
}
.studio .btn:disabled {
  opacity: 0.45;
}
.studio .btn.solid {
  border-color: transparent;
  background: var(--text);
  color: #0b0c0e;
  font-weight: 600;
}
.studio .btn.solid:hover:not(:disabled) {
  background: #fff;
}
.studio .btn.danger {
  border-color: rgba(229, 72, 77, 0.35);
  background: var(--bad-soft);
  color: var(--bad-text);
}
.studio .btn.danger:hover:not(:disabled) {
  background: rgba(229, 72, 77, 0.16);
  border-color: rgba(229, 72, 77, 0.5);
}
.studio .btn kbd {
  margin-left: 2px;
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 500;
  opacity: 0.5;
}

.studio .dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .dot.passed {
  background: var(--good);
}
.studio .dot.failed {
  background: var(--bad);
}
.studio .dot.running,
.studio .dot.queued {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .dot.stopped,
.studio .dot.idle {
  background: transparent;
  border: 1.5px solid var(--text-3);
}

.studio .status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .status.passed,
.studio .status.pass {
  color: var(--good-text);
}
.studio .status.passed i,
.studio .status.pass i {
  background: var(--good);
}
.studio .status.failed,
.studio .status.fail {
  color: var(--bad-text);
}
.studio .status.failed i,
.studio .status.fail i {
  background: var(--bad);
}
.studio .status.running,
.studio .status.queued {
  color: var(--accent);
}
.studio .status.running i,
.studio .status.queued i {
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(245, 200, 76, 0.45);
  }
  50% {
    box-shadow: 0 0 0 4px rgba(245, 200, 76, 0);
  }
}

.studio .check-icon {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  color: var(--text-3);
}
.studio .check-icon .ico {
  stroke-width: 2.2;
}
.studio .check-icon.pass {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .check-icon.fail {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .check-icon.blocked {
  border-color: transparent;
  background: rgba(240, 180, 41, 0.12);
  color: var(--warn);
}
.studio .check-icon.running {
  border-color: var(--accent);
  border-right-color: transparent;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.studio .panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .panel.pad {
  padding: 18px 20px;
}
.studio .panel-head {
  padding: 14px 16px 4px;
}

.studio .section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 24px;
  margin-bottom: 8px;
}
.studio .section-head h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.studio .count {
  padding: 0 6px;
  border-radius: 99px;
  background: var(--raised);
  color: var(--text-3);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.studio .block + .block {
  margin-top: 26px;
}

.studio .segmented {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--line);
}
.studio .segmented button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .segmented button:hover {
  color: var(--text);
}
.studio .segmented button.on {
  background: var(--raised);
  color: var(--text);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 1px 2px rgba(0, 0, 0, 0.4);
}
.studio .segmented span {
  color: var(--text-3);
  font-size: 11px;
}

.studio .tabs {
  display: flex;
  gap: 20px;
  margin-top: 18px;
  border-bottom: 1px solid var(--line);
}
.studio .tabs button {
  position: relative;
  height: 36px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 13px;
  font-weight: 500;
}
.studio .tabs button:hover {
  color: var(--text-2);
}
.studio .tabs button.on {
  color: var(--text);
}
.studio .tabs button.on::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  border-radius: 2px;
  background: var(--text);
}

.studio .table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}
.studio .table th {
  padding: 0 12px 9px;
  border-bottom: 1px solid var(--line);
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
  text-align: left;
  white-space: nowrap;
}
.studio .table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  vertical-align: middle;
}
.studio .table th:first-child,
.studio .table td:first-child {
  padding-left: 0;
}
.studio .table th:last-child,
.studio .table td:last-child {
  padding-right: 0;
}
.studio .table tr:last-child td {
  border-bottom: 0;
}
.studio .table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .panel > .table th:first-child,
.studio .panel > .table td:first-child {
  padding-left: 18px;
}
.studio .panel > .table th:last-child,
.studio .panel > .table td:last-child {
  padding-right: 18px;
}
.studio .panel > .table th {
  padding-top: 14px;
}
.studio .table.selectable tbody tr {
  cursor: pointer;
}
.studio .table.selectable tbody tr:hover td {
  background: rgba(255, 255, 255, 0.02);
}
.studio .table.selectable tbody tr.selected td {
  background: rgba(255, 255, 255, 0.045);
}

.studio .meter {
  display: block;
  width: 100%;
  min-width: 60px;
  height: 6px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.studio .meter i {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: var(--text-2);
}

.studio .facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 18px 0 0;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .facts > div {
  padding: 10px 14px;
}
.studio .facts > div + div {
  border-left: 1px solid var(--line);
}
.studio .facts dt {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .facts dd {
  margin: 2px 0 0;
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .facts.stacked {
  grid-template-columns: 1fr;
  margin: 14px 0;
}
.studio .facts.stacked > div + div {
  border-left: 0;
  border-top: 1px solid var(--line);
}
.studio .facts.stacked dd {
  font-size: 12.5px;
  font-weight: 500;
  word-break: break-all;
}

/* ---------- Shell ---------- */

.studio .side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 14px 10px 10px;
  border-right: 1px solid var(--line);
  background: var(--side);
}
.studio .logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 2px 8px 14px;
}
.studio .logo strong {
  display: block;
  font-family: var(--display);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
}
.studio .logo small {
  display: block;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .brand-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--accent);
  color: #1b1503;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
}
.studio .new-mod {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  margin: 0 0 14px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}
.studio .new-mod:hover {
  background: var(--hover);
}
.studio .nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.studio .nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .nav-item svg {
  width: 17px;
  height: 17px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.85;
}
.studio .nav-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .nav-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
  font-weight: 500;
}
.studio .live-dot {
  width: 6px;
  height: 6px;
  margin-left: auto;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
.studio .side-section {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  margin-top: 22px;
}
.studio .side-label {
  display: block;
  padding: 0 10px 6px;
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
}
.studio .recents {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.studio .recent-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  height: 30px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
  text-align: left;
}
.studio .recent-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .recent-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
}
.studio .recent-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .recent-item small {
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.studio .side-empty {
  padding: 4px 10px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .side-foot {
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.studio .runtime-status {
  display: grid;
  gap: 6px;
  padding: 4px 10px 10px;
}
.studio .runtime-status > div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .runtime-status small {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .runtime-status .dot.passed {
  box-shadow: 0 0 0 3px var(--good-soft);
}
.studio .mock-note {
  justify-self: start;
  margin-top: 2px;
  padding: 0 7px;
  border: 1px dashed var(--line-strong);
  border-radius: 99px;
  color: var(--text-3);
  font-size: 11px;
  line-height: 18px;
}

.studio-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.studio .view {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 18px;
  min-height: 0;
  padding: 26px 32px 40px;
  overflow-y: auto;
}
.studio .view.fill {
  overflow: hidden;
  padding-bottom: 24px;
}
.studio .page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}
.studio .page-head h1 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .page-head p {
  margin-top: 3px;
  color: var(--text-2);
}
.studio .page-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
}

/* ---------- Partners ---------- */

.studio .partner-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-dot.entire {
  background: var(--entire);
}
.studio .partner-dot.neatlogs {
  background: var(--neatlogs);
}
.studio .partner-dot.off {
  background: transparent;
  border: 1.5px solid var(--text-3);
}
.studio .partner-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio button.partner-link:hover {
  border-color: var(--line-strong);
  color: var(--text);
}
.studio .partner-link i {
  width: 6px;
  height: 6px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-link.neatlogs i {
  background: var(--neatlogs);
}
.studio .partner-link.entire i {
  background: var(--entire);
}
.studio .partner-link.off i {
  background: transparent;
  border: 1px solid var(--text-3);
}
.studio .partner-link.static {
  font-family: var(--mono);
  font-size: 11px;
}
.studio .partners {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .partners li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12.5px;
}
.studio .partners strong {
  font-weight: 500;
}
.studio .partners .meta {
  margin-left: auto;
}

/* ---------- Test plan and attempts ---------- */

.studio .check-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .check-list li {
  display: flex;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .check-list li:first-child {
  border-top: 0;
}
.studio .check-list strong {
  display: block;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  line-height: 18px;
}
.studio .check-list p {
  margin-top: 3px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .check-list li.fail p {
  color: var(--text-2);
}

.studio .attempts {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .attempt {
  position: relative;
  padding-bottom: 18px;
}
.studio .attempt:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 22px;
  bottom: 2px;
  left: 8.5px;
  width: 1px;
  background: var(--line-strong);
}
.studio .attempt-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 20px;
}
.studio .attempt-head strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .attempt-head .status {
  margin-left: auto;
}
.studio .attempt-body {
  display: grid;
  gap: 10px;
  padding: 8px 0 0 28px;
}
.studio .attempt-text {
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .lesson {
  padding: 9px 12px;
  border-left: 2px solid var(--good);
  border-radius: 0 6px 6px 0;
  background: var(--good-soft);
}
.studio .lesson span {
  display: block;
  margin-bottom: 2px;
  color: var(--good-text);
  font-size: 11.5px;
  font-weight: 600;
}
.studio .lesson p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .attempt-refs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.studio .sha {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio button.sha:hover:not(:disabled) {
  border-color: var(--line-strong);
}
.studio .sha.static,
.studio button.sha:disabled {
  opacity: 1;
}
.studio .sessions {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .sessions li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  min-width: 0;
  padding: 7px 10px;
}
.studio .sessions li + li {
  border-top: 1px solid var(--line);
}
.studio .session-role {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 500;
}
.studio .sessions .meta {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Build: composer ---------- */

.studio .compose-page {
  align-items: center;
}
.studio .compose {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
  max-width: 720px;
  padding-top: 7vh;
}
.studio .compose h1 {
  font-family: var(--display);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.studio .lede {
  max-width: 600px;
  margin-top: -8px !important;
  color: var(--text-2);
  font-size: 14px;
}
.studio .running-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
  border: 1px solid rgba(245, 200, 76, 0.25);
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--text-2);
  text-align: left;
}
.studio .running-banner strong {
  color: var(--text);
  font-weight: 600;
}
.studio .banner-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: var(--text);
  font-weight: 500;
}
.studio .prompt-box {
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 12px 32px -16px rgba(0, 0, 0, 0.6);
  transition: border-color 0.15s;
}
.studio .prompt-box:focus-within {
  border-color: rgba(255, 255, 255, 0.24);
}
.studio .prompt-box textarea {
  display: block;
  width: 100%;
  min-height: 112px;
  padding: 16px 18px 8px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 15px;
  line-height: 1.55;
  resize: none;
}
.studio .prompt-box textarea::placeholder {
  color: var(--text-3);
}
.studio .prompt-box.seeded textarea {
  opacity: 0.4;
}
.studio .composer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 10px 10px 16px;
}
.studio .toggle {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12.5px;
  cursor: pointer;
  user-select: none;
}
.studio .toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.studio .switch {
  position: relative;
  width: 28px;
  height: 16px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.15s;
}
.studio .switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text);
  transition: transform 0.15s;
}
.studio .toggle input:checked + .switch {
  background: var(--accent);
}
.studio .toggle input:checked + .switch::after {
  transform: translateX(12px);
  background: #1b1503;
}
.studio .toggle input:focus-visible + .switch {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio .examples {
  display: grid;
  gap: 2px;
}
.studio .examples .side-label {
  padding: 4px 0 6px;
}
.studio .examples button {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  margin: 0 -12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .examples button span {
  flex: 1;
}
.studio .examples button .ico {
  opacity: 0;
  transition: opacity 0.12s, transform 0.12s;
}
.studio .examples button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .examples button:hover:not(:disabled) .ico {
  opacity: 1;
  transform: translateX(2px);
}
.studio .examples button:disabled {
  opacity: 0.4;
}
.studio .flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 12px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  list-style: none;
  gap: 18px;
}
.studio .flow li {
  display: grid;
  gap: 4px;
}
.studio .flow-n {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-bottom: 4px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  color: var(--text-3);
  font-size: 11px;
  font-weight: 600;
}
.studio .flow strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .flow p {
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
}
.studio .lessons {
  margin-top: 8px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .lessons .section-head {
  margin-bottom: 0;
}
.studio .lessons ul,
.studio .lesson-list {
  display: grid;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .lessons li,
.studio .lesson-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .lessons li p,
.studio .lesson-list li p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .lessons li small,
.studio .lesson-list li small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Build: run view ---------- */

.studio .run-page {
  gap: 16px;
  padding: 22px 28px 22px;
  overflow: hidden;
}
.studio .run-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
.studio .run-title {
  min-width: 0;
}
.studio .run-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}
.studio .run-name h1,
.studio .run-name h2 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .run-name h2 {
  font-size: 19px;
}
.studio .run-title p,
.studio .detail-title p {
  max-width: 820px;
  margin-top: 4px;
  overflow: hidden;
  color: var(--text-2);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.studio .pipeline {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  list-style: none;
}
.studio .pipeline li {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--text-3);
  font-size: 12.5px;
  white-space: nowrap;
}
.studio .pipeline li::after {
  content: "";
  flex: 1;
  height: 1px;
  min-width: 8px;
  margin: 0 10px;
  background: var(--line-strong);
}
.studio .pipeline li:nth-last-child(2) {
  flex: none;
}
.studio .pipeline li:nth-last-child(2)::after,
.studio .pipeline .pipe-meta::after {
  display: none;
}
.studio .pipe-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
}
.studio .pipe-icon .ico {
  stroke-width: 2.4;
}
.studio .pipeline li.done {
  color: var(--text-2);
}
.studio .pipeline li.done::after {
  background: rgba(76, 195, 138, 0.4);
}
.studio .pipeline li.done .pipe-icon {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .pipeline li.current {
  color: var(--text);
  font-weight: 600;
}
.studio .pipeline li.current .pipe-icon {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .pipeline li.current .pipe-icon::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}
.studio .pipeline li.failed {
  color: var(--bad-text);
  font-weight: 600;
}
.studio .pipeline li.failed .pipe-icon {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .pipeline .pipe-meta {
  flex: none;
  margin-left: 18px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
  color: var(--text-2);
  font-weight: 500;
}

.studio .run-grid {
  display: grid;
  flex: 1;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 16px;
  min-height: 0;
}
.studio .run-stage {
  display: grid;
  grid-template-rows: minmax(0, 3fr) minmax(170px, 2fr);
  gap: 16px;
  min-height: 0;
}
.studio .run-side {
  min-height: 0;
  padding: 16px 18px 20px;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}

.studio .activity {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  overflow: hidden;
}
.studio .activity-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
}
.studio .activity-head h3 {
  font-size: 13px;
  font-weight: 600;
}
.studio .activity-body {
  flex: 1;
  min-height: 0;
  padding: 6px 0;
  overflow-y: auto;
}
.studio .activity-body .empty {
  padding: 14px;
}
.studio .event {
  display: grid;
  grid-template-columns: 62px 96px minmax(0, 1fr);
  gap: 10px;
  padding: 4px 14px;
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .event:hover {
  background: rgba(255, 255, 255, 0.02);
}
.studio .event time {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11px;
  line-height: 20px;
}
.studio .event-role {
  display: flex;
  align-items: baseline;
  gap: 4px;
  overflow: hidden;
  color: var(--text-3);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .event-role small {
  color: var(--text-3);
  font-size: 11px;
  font-weight: 400;
}
.studio .event-role.playtester {
  color: #8fc7f5;
}
.studio .event-role.builder {
  color: #c7b4fa;
}
.studio .event-role.fixer {
  color: #f5b98f;
}
.studio .event-role.spec {
  color: #a8dcc2;
}
.studio .event-role.benana {
  color: var(--accent);
}
.studio .event-text {
  min-width: 0;
  color: var(--text-2);
  overflow-wrap: anywhere;
}
.studio .event-text code {
  margin-right: 8px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event-text .result {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event.text .event-text,
.studio .event.phase .event-text {
  color: var(--text);
}
.studio .event.failure .event-text,
.studio .event.error .event-text {
  color: var(--bad-text);
}

/* ---------- Mods ---------- */

.studio .mods {
  display: grid;
  flex: 1;
  grid-template-columns: 340px minmax(0, 1fr);
  gap: 16px;
  min-height: 0;
}
.studio .mods-list {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 12px;
}
.studio .mods-list .segmented {
  align-self: flex-start;
  margin-bottom: 10px;
}
.studio .list {
  display: grid;
  align-content: start;
  gap: 1px;
  min-height: 0;
  overflow-y: auto;
}
.studio .list-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  text-align: left;
}
.studio .list-row:hover {
  background: rgba(255, 255, 255, 0.035);
}
.studio .list-row.active {
  background: rgba(255, 255, 255, 0.07);
}
.studio .list-main {
  flex: 1;
  min-width: 0;
}
.studio .list-main strong {
  display: block;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .list-main small {
  color: var(--text-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}
.studio .entire-split .list {
  padding: 0 8px 8px;
}
.studio .mods-detail {
  min-height: 0;
  padding: 20px 24px 28px;
  overflow-y: auto;
}
.studio .detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}
.studio .detail-title {
  min-width: 0;
}
.studio .overview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 36px;
  padding-top: 22px;
}
.studio .overview-col {
  min-width: 0;
}
.studio .prose {
  color: var(--text-2);
  line-height: 1.6;
}
.studio .bullets {
  margin: 10px 0 0;
  padding-left: 18px;
  color: var(--text-2);
}
.studio .bullets li {
  padding: 2px 0;
}
.studio .bullets li::marker {
  color: var(--text-3);
}

/* ---------- Code ---------- */

.studio .code {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 18px;
}
.studio .code .segmented {
  align-self: flex-start;
}
.studio .code-split {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: 420px;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.studio .file-tree {
  padding: 10px 8px;
  border-right: 1px solid var(--line);
  background: var(--bg);
  overflow-y: auto;
}
.studio .tree-group + .tree-group {
  margin-top: 10px;
}
.studio .tree-group small {
  display: block;
  padding: 2px 8px 4px;
  overflow: hidden;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button {
  display: block;
  width: 100%;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .file-tree button.on {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
}
.studio .commit-list button {
  display: grid;
  gap: 1px;
  font-family: var(--sans);
  font-size: 12.5px;
}
.studio .commit-list small {
  color: var(--text-3);
  font-size: 11px;
}
.studio .viewer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #0d0e11;
}
.studio .viewer-head {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  font-size: 11.5px;
}
.studio .code-body {
  flex: 1;
  max-height: 62vh;
  padding: 8px 0;
  overflow: auto;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.65;
}
.studio .code-line {
  display: flex;
  min-width: max-content;
  padding-right: 16px;
}
.studio .code-line .ln {
  flex: none;
  width: 48px;
  padding-right: 14px;
  color: #4b4f58;
  text-align: right;
  user-select: none;
}
.studio .code-line .lc {
  color: #d4d6dc;
  white-space: pre;
}
.studio .code-line:not(:has(.ln)) .lc {
  padding-left: 16px;
}
.studio .code-line.add {
  background: rgba(76, 195, 138, 0.09);
}
.studio .code-line.add .lc {
  color: #9be0bd;
}
.studio .code-line.del {
  background: rgba(229, 72, 77, 0.09);
}
.studio .code-line.del .lc {
  color: #f5a3a6;
}
.studio .code-line.hunk .lc {
  color: #8fc7f5;
}
.studio .code-line.meta .lc {
  color: var(--text-3);
}

/* ---------- Insights ---------- */

.studio .kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .kpis.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.studio .kpi {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 16px 20px;
}
.studio .kpi + .kpi {
  border-left: 1px solid var(--line);
}
.studio .kpi span {
  color: var(--text-2);
  font-size: 12px;
}
.studio .kpi strong {
  margin-top: 4px;
  color: var(--text);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.studio .kpi small {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .legend {
  display: flex;
  gap: 16px;
}
.studio .lg {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .lg::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .lg.passed::before {
  background: var(--good);
}
.studio .lg.failed::before {
  background: var(--bad);
}
.studio .lg.running::before {
  background: var(--accent);
}
.studio .chart {
  position: relative;
  margin-top: 14px;
}
.studio .daily {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.studio .daily .axis {
  stroke: var(--line-strong);
}
.studio .daily .grid {
  stroke: var(--line);
  stroke-dasharray: 2 4;
}
.studio .daily .tick {
  fill: var(--text-3);
  font-size: 11px;
}
.studio .daily .hit {
  fill: transparent;
}
.studio .daily .hover-band {
  fill: rgba(255, 255, 255, 0.04);
}
.studio .daily .passed {
  fill: var(--good);
}
.studio .daily .failed {
  fill: var(--bad);
}
.studio .daily .running {
  fill: var(--accent);
}
.studio .tooltip {
  position: absolute;
  top: 0;
  z-index: 2;
  display: grid;
  gap: 3px;
  min-width: 140px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #1a1c21;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  pointer-events: none;
  transform: translate(-50%, -8px);
}
.studio .tooltip strong {
  margin-bottom: 2px;
  font-weight: 600;
}
.studio .tooltip span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
}
.studio .tooltip i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .tooltip i.passed {
  background: var(--good);
}
.studio .tooltip i.failed {
  background: var(--bad);
}
.studio .tooltip i.running {
  background: var(--accent);
}
.studio .tooltip b {
  margin-left: auto;
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .insight-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.studio .insight-grid .section-head ~ .section-head {
  margin-top: 22px;
}
.studio .hbars {
  display: grid;
  gap: 10px;
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}
.studio .hbars li {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 12px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .hbars strong {
  color: var(--text);
  font-weight: 600;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .coverage-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.studio .coverage {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .coverage .partner-dot {
  margin-top: 6px;
}
.studio .coverage strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.studio .coverage span {
  display: block;
  color: var(--text);
  font-size: 12.5px;
}
.studio .coverage small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Neatlogs and Entire ---------- */

.studio .connection {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .connection strong {
  flex: none;
  font-weight: 600;
}
.studio .connection .meta {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  align-items: start;
  gap: 16px;
}
.studio .split > .panel:first-child {
  overflow-x: auto;
}
.studio .entire-split {
  grid-template-columns: 300px minmax(0, 1fr);
}
.studio .detail-card {
  position: sticky;
  top: 0;
}
.studio .trace {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .trace-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.studio .trace-head strong {
  font-weight: 600;
}
.studio .spans {
  display: grid;
  gap: 1px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .spans li {
  display: grid;
  padding: 5px 0 5px 12px;
  border-left: 2px solid rgba(79, 184, 208, 0.5);
  color: var(--text-2);
  font-size: 12px;
}
.studio .spans li.failed {
  border-left-color: var(--bad);
  color: var(--bad-text);
}
.studio .spans small {
  color: var(--text-3);
}
.studio .commits {
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .commits li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
}
.studio .commits li:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 26px;
  bottom: -10px;
  left: 4px;
  width: 1px;
  background: var(--line-strong);
}
.studio .commit-node {
  flex: none;
  width: 9px;
  height: 9px;
  border: 2px solid var(--good);
  border-radius: 50%;
  background: var(--panel);
}
.studio .commits li.bad .commit-node {
  border-color: var(--bad);
}
.studio .commit-main {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}
.studio .commit-main strong {
  font-weight: 500;
}

@media (max-width: 1360px) {
  .studio .run-grid {
    grid-template-columns: minmax(0, 1fr) 340px;
  }
  .studio .kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .studio .kpi:nth-child(4) {
    border-left: 0;
  }
  .studio .kpi:nth-child(n + 4) {
    border-top: 1px solid var(--line);
  }
  .studio .pipeline li > span:last-child {
    display: none;
  }
  .studio .pipeline li.current > span:last-child,
  .studio .pipeline li.failed > span:last-child,
  .studio .pipeline .pipe-meta {
    display: inline;
  }
}
@media (max-width: 1180px) {
  .studio {
    grid-template-columns: 200px minmax(0, 1fr);
  }
  .studio .insight-grid,
  .studio .overview,
  .studio .split,
  .studio .entire-split {
    grid-template-columns: 1fr;
  }
  .studio .mods {
    grid-template-columns: 280px minmax(0, 1fr);
  }
  .studio .flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

toolUseResult.content:
/* Mod Studio: calm dark workbench. One accent (banana) for live state; status by dot + label. */

.studio {
  --bg: #0b0c0e;
  --side: #0e0f12;
  --panel: #121317;
  --raised: #17191d;
  --hover: #1c1e23;
  --line: rgba(255, 255, 255, 0.07);
  --line-strong: rgba(255, 255, 255, 0.12);
  --text: #ececef;
  --text-2: #a3a6ae;
  --text-3: #6e727c;
  --accent: #f5c84c;
  --accent-soft: rgba(245, 200, 76, 0.12);
  --good: #4cc38a;
  --good-text: #74d6a6;
  --good-soft: rgba(76, 195, 138, 0.12);
  --warn: #f0b429;
  --bad: #e5484d;
  --bad-text: #f2777b;
  --bad-soft: rgba(229, 72, 77, 0.1);
  --neatlogs: #4fb8d0;
  --entire: #a78bfa;
  --sans: "Segoe UI Variable Text", "Segoe UI", Inter, system-ui, sans-serif;
  --display: "Segoe UI Variable Display", "Segoe UI", Inter, system-ui, sans-serif;
  --mono: "Cascadia Code", "JetBrains Mono", Consolas, monospace;

  display: grid;
  grid-template-columns: 236px minmax(0, 1fr);
  height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
.studio *,
.studio *::before,
.studio *::after {
  box-sizing: border-box;
}
.studio button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.studio button:disabled {
  cursor: default;
}
.studio :focus-visible {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio h1,
.studio h2,
.studio h3,
.studio p {
  margin: 0;
}
.studio ::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.studio ::-webkit-scrollbar-track {
  background: transparent;
}
.studio ::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09) padding-box;
}
.studio ::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.18) padding-box;
}
.studio ::-webkit-scrollbar-corner {
  background: transparent;
}

/* ---------- Shared primitives ---------- */

.studio .ico {
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.studio .meta {
  color: var(--text-3);
  font-size: 12px;
}
.studio .muted {
  color: var(--text-3);
}
.studio .mono {
  font-family: var(--mono);
  font-size: 12px;
}
.studio .strong {
  color: var(--text);
  font-weight: 500;
}
.studio .empty {
  padding: 14px 0;
  color: var(--text-3);
  font-size: 12.5px;
}
.studio .alert {
  padding: 9px 12px;
  border: 1px solid rgba(229, 72, 77, 0.28);
  border-radius: 8px;
  background: var(--bad-soft);
  color: var(--bad-text);
  font-size: 12.5px;
}
.studio .page-alert {
  margin: 16px 32px 0;
}
.studio .tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio .link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .link:hover {
  color: var(--text);
}

.studio .btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition: background 0.12s, border-color 0.12s;
}
.studio .btn:hover:not(:disabled) {
  background: var(--hover);
  border-color: rgba(255, 255, 255, 0.18);
}
.studio .btn:disabled {
  opacity: 0.45;
}
.studio .btn.solid {
  border-color: transparent;
  background: var(--text);
  color: #0b0c0e;
  font-weight: 600;
}
.studio .btn.solid:hover:not(:disabled) {
  background: #fff;
}
.studio .btn.danger {
  border-color: rgba(229, 72, 77, 0.35);
  background: var(--bad-soft);
  color: var(--bad-text);
}
.studio .btn.danger:hover:not(:disabled) {
  background: rgba(229, 72, 77, 0.16);
  border-color: rgba(229, 72, 77, 0.5);
}
.studio .btn kbd {
  margin-left: 2px;
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 500;
  opacity: 0.5;
}

.studio .dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .dot.passed {
  background: var(--good);
}
.studio .dot.failed {
  background: var(--bad);
}
.studio .dot.running,
.studio .dot.queued {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .dot.stopped,
.studio .dot.idle {
  background: transparent;
  border: 1.5px solid var(--text-3);
}

.studio .status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .status.passed,
.studio .status.pass {
  color: var(--good-text);
}
.studio .status.passed i,
.studio .status.pass i {
  background: var(--good);
}
.studio .status.failed,
.studio .status.fail {
  color: var(--bad-text);
}
.studio .status.failed i,
.studio .status.fail i {
  background: var(--bad);
}
.studio .status.running,
.studio .status.queued {
  color: var(--accent);
}
.studio .status.running i,
.studio .status.queued i {
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(245, 200, 76, 0.45);
  }
  50% {
    box-shadow: 0 0 0 4px rgba(245, 200, 76, 0);
  }
}

.studio .check-icon {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
  color: var(--text-3);
}
.studio .check-icon .ico {
  stroke-width: 2.2;
}
.studio .check-icon.pass {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .check-icon.fail {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .check-icon.blocked {
  border-color: transparent;
  background: rgba(240, 180, 41, 0.12);
  color: var(--warn);
}
.studio .check-icon.running {
  border-color: var(--accent);
  border-right-color: transparent;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.studio .panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .panel.pad {
  padding: 18px 20px;
}
.studio .panel-head {
  padding: 14px 16px 4px;
}

.studio .section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 24px;
  margin-bottom: 8px;
}
.studio .section-head h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.studio .count {
  padding: 0 6px;
  border-radius: 99px;
  background: var(--raised);
  color: var(--text-3);
  font-size: 11px;
  font-weight: 500;
  line-height: 18px;
}
.studio .block + .block {
  margin-top: 26px;
}

.studio .segmented {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--line);
}
.studio .segmented button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .segmented button:hover {
  color: var(--text);
}
.studio .segmented button.on {
  background: var(--raised);
  color: var(--text);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 1px 2px rgba(0, 0, 0, 0.4);
}
.studio .segmented span {
  color: var(--text-3);
  font-size: 11px;
}

.studio .tabs {
  display: flex;
  gap: 20px;
  margin-top: 18px;
  border-bottom: 1px solid var(--line);
}
.studio .tabs button {
  position: relative;
  height: 36px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-3);
  font-size: 13px;
  font-weight: 500;
}
.studio .tabs button:hover {
  color: var(--text-2);
}
.studio .tabs button.on {
  color: var(--text);
}
.studio .tabs button.on::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  border-radius: 2px;
  background: var(--text);
}

.studio .table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}
.studio .table th {
  padding: 0 12px 9px;
  border-bottom: 1px solid var(--line);
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
  text-align: left;
  white-space: nowrap;
}
.studio .table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  vertical-align: middle;
}
.studio .table th:first-child,
.studio .table td:first-child {
  padding-left: 0;
}
.studio .table th:last-child,
.studio .table td:last-child {
  padding-right: 0;
}
.studio .table tr:last-child td {
  border-bottom: 0;
}
.studio .table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .panel > .table th:first-child,
.studio .panel > .table td:first-child {
  padding-left: 18px;
}
.studio .panel > .table th:last-child,
.studio .panel > .table td:last-child {
  padding-right: 18px;
}
.studio .panel > .table th {
  padding-top: 14px;
}
.studio .table.selectable tbody tr {
  cursor: pointer;
}
.studio .table.selectable tbody tr:hover td {
  background: rgba(255, 255, 255, 0.02);
}
.studio .table.selectable tbody tr.selected td {
  background: rgba(255, 255, 255, 0.045);
}

.studio .meter {
  display: block;
  width: 100%;
  min-width: 60px;
  height: 6px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.studio .meter i {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: var(--text-2);
}

.studio .facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 18px 0 0;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .facts > div {
  padding: 10px 14px;
}
.studio .facts > div + div {
  border-left: 1px solid var(--line);
}
.studio .facts dt {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .facts dd {
  margin: 2px 0 0;
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .facts.stacked {
  grid-template-columns: 1fr;
  margin: 14px 0;
}
.studio .facts.stacked > div + div {
  border-left: 0;
  border-top: 1px solid var(--line);
}
.studio .facts.stacked dd {
  font-size: 12.5px;
  font-weight: 500;
  word-break: break-all;
}

/* ---------- Shell ---------- */

.studio .side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 14px 10px 10px;
  border-right: 1px solid var(--line);
  background: var(--side);
}
.studio .logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 2px 8px 14px;
}
.studio .logo strong {
  display: block;
  font-family: var(--display);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
}
.studio .logo small {
  display: block;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .brand-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--accent);
  color: #1b1503;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
}
.studio .new-mod {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  margin: 0 0 14px;
  padding: 0 10px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--raised);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}
.studio .new-mod:hover {
  background: var(--hover);
}
.studio .nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.studio .nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .nav-item svg {
  width: 17px;
  height: 17px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.85;
}
.studio .nav-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .nav-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
  font-weight: 500;
}
.studio .live-dot {
  width: 6px;
  height: 6px;
  margin-left: auto;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 1.6s ease-in-out infinite;
}
.studio .side-section {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  margin-top: 22px;
}
.studio .side-label {
  display: block;
  padding: 0 10px 6px;
  color: var(--text-3);
  font-size: 11.5px;
  font-weight: 500;
}
.studio .recents {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.studio .recent-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  height: 30px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-2);
  font-size: 12.5px;
  text-align: left;
}
.studio .recent-item:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .recent-item.active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
}
.studio .recent-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .recent-item small {
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.studio .side-empty {
  padding: 4px 10px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .side-foot {
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.studio .runtime-status {
  display: grid;
  gap: 6px;
  padding: 4px 10px 10px;
}
.studio .runtime-status > div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .runtime-status small {
  margin-left: auto;
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .runtime-status .dot.passed {
  box-shadow: 0 0 0 3px var(--good-soft);
}
.studio .mock-note {
  justify-self: start;
  margin-top: 2px;
  padding: 0 7px;
  border: 1px dashed var(--line-strong);
  border-radius: 99px;
  color: var(--text-3);
  font-size: 11px;
  line-height: 18px;
}

.studio-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.studio .view {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 18px;
  min-height: 0;
  padding: 26px 32px 40px;
  overflow-y: auto;
}
.studio .view.fill {
  overflow: hidden;
  padding-bottom: 24px;
}
.studio .page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}
.studio .page-head h1 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .page-head p {
  margin-top: 3px;
  color: var(--text-2);
}
.studio .page-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
}

/* ---------- Partners ---------- */

.studio .partner-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-dot.entire {
  background: var(--entire);
}
.studio .partner-dot.neatlogs {
  background: var(--neatlogs);
}
.studio .partner-dot.off {
  background: transparent;
  border: 1.5px solid var(--text-3);
}
.studio .partner-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-size: 11.5px;
  white-space: nowrap;
}
.studio button.partner-link:hover {
  border-color: var(--line-strong);
  color: var(--text);
}
.studio .partner-link i {
  width: 6px;
  height: 6px;
  border-radius: 2px;
  background: var(--text-3);
}
.studio .partner-link.neatlogs i {
  background: var(--neatlogs);
}
.studio .partner-link.entire i {
  background: var(--entire);
}
.studio .partner-link.off i {
  background: transparent;
  border: 1px solid var(--text-3);
}
.studio .partner-link.static {
  font-family: var(--mono);
  font-size: 11px;
}
.studio .partners {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .partners li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12.5px;
}
.studio .partners strong {
  font-weight: 500;
}
.studio .partners .meta {
  margin-left: auto;
}

/* ---------- Test plan and attempts ---------- */

.studio .check-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .check-list li {
  display: flex;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .check-list li:first-child {
  border-top: 0;
}
.studio .check-list strong {
  display: block;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  line-height: 18px;
}
.studio .check-list p {
  margin-top: 3px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .check-list li.fail p {
  color: var(--text-2);
}

.studio .attempts {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .attempt {
  position: relative;
  padding-bottom: 18px;
}
.studio .attempt:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 22px;
  bottom: 2px;
  left: 8.5px;
  width: 1px;
  background: var(--line-strong);
}
.studio .attempt-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 20px;
}
.studio .attempt-head strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .attempt-head .status {
  margin-left: auto;
}
.studio .attempt-body {
  display: grid;
  gap: 10px;
  padding: 8px 0 0 28px;
}
.studio .attempt-text {
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .lesson {
  padding: 9px 12px;
  border-left: 2px solid var(--good);
  border-radius: 0 6px 6px 0;
  background: var(--good-soft);
}
.studio .lesson span {
  display: block;
  margin-bottom: 2px;
  color: var(--good-text);
  font-size: 11.5px;
  font-weight: 600;
}
.studio .lesson p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .attempt-refs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.studio .sha {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio button.sha:hover:not(:disabled) {
  border-color: var(--line-strong);
}
.studio .sha.static,
.studio button.sha:disabled {
  opacity: 1;
}
.studio .sessions {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .sessions li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  min-width: 0;
  padding: 7px 10px;
}
.studio .sessions li + li {
  border-top: 1px solid var(--line);
}
.studio .session-role {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 500;
}
.studio .sessions .meta {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Build: composer ---------- */

.studio .compose-page {
  align-items: center;
}
.studio .compose {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
  max-width: 720px;
  padding-top: 7vh;
}
.studio .compose h1 {
  font-family: var(--display);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.studio .lede {
  max-width: 600px;
  margin-top: -8px !important;
  color: var(--text-2);
  font-size: 14px;
}
.studio .running-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
  border: 1px solid rgba(245, 200, 76, 0.25);
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--text-2);
  text-align: left;
}
.studio .running-banner strong {
  color: var(--text);
  font-weight: 600;
}
.studio .banner-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: var(--text);
  font-weight: 500;
}
.studio .prompt-box {
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 12px 32px -16px rgba(0, 0, 0, 0.6);
  transition: border-color 0.15s;
}
.studio .prompt-box:focus-within {
  border-color: rgba(255, 255, 255, 0.24);
}
.studio .prompt-box textarea {
  display: block;
  width: 100%;
  min-height: 112px;
  padding: 16px 18px 8px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 15px;
  line-height: 1.55;
  resize: none;
}
.studio .prompt-box textarea::placeholder {
  color: var(--text-3);
}
.studio .prompt-box.seeded textarea {
  opacity: 0.4;
}
.studio .composer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 10px 10px 16px;
}
.studio .toggle {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--text-2);
  font-size: 12.5px;
  cursor: pointer;
  user-select: none;
}
.studio .toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.studio .switch {
  position: relative;
  width: 28px;
  height: 16px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.15s;
}
.studio .switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text);
  transition: transform 0.15s;
}
.studio .toggle input:checked + .switch {
  background: var(--accent);
}
.studio .toggle input:checked + .switch::after {
  transform: translateX(12px);
  background: #1b1503;
}
.studio .toggle input:focus-visible + .switch {
  outline: 2px solid rgba(245, 200, 76, 0.55);
  outline-offset: 2px;
}
.studio .examples {
  display: grid;
  gap: 2px;
}
.studio .examples .side-label {
  padding: 4px 0 6px;
}
.studio .examples button {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  margin: 0 -12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-2);
  font-size: 13px;
  text-align: left;
}
.studio .examples button span {
  flex: 1;
}
.studio .examples button .ico {
  opacity: 0;
  transition: opacity 0.12s, transform 0.12s;
}
.studio .examples button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .examples button:hover:not(:disabled) .ico {
  opacity: 1;
  transform: translateX(2px);
}
.studio .examples button:disabled {
  opacity: 0.4;
}
.studio .flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin: 12px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  list-style: none;
  gap: 18px;
}
.studio .flow li {
  display: grid;
  gap: 4px;
}
.studio .flow-n {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-bottom: 4px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  color: var(--text-3);
  font-size: 11px;
  font-weight: 600;
}
.studio .flow strong {
  font-size: 13px;
  font-weight: 600;
}
.studio .flow p {
  color: var(--text-3);
  font-size: 12px;
  line-height: 1.5;
}
.studio .lessons {
  margin-top: 8px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .lessons .section-head {
  margin-bottom: 0;
}
.studio .lessons ul,
.studio .lesson-list {
  display: grid;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .lessons li,
.studio .lesson-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.studio .lessons li p,
.studio .lesson-list li p {
  color: var(--text);
  font-size: 12.5px;
}
.studio .lessons li small,
.studio .lesson-list li small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Build: run view ---------- */

.studio .run-page {
  gap: 16px;
  padding: 22px 28px 22px;
  overflow: hidden;
}
.studio .run-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
.studio .run-title {
  min-width: 0;
}
.studio .run-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}
.studio .run-name h1,
.studio .run-name h2 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.studio .run-name h2 {
  font-size: 19px;
}
.studio .run-title p,
.studio .detail-title p {
  max-width: 820px;
  margin-top: 4px;
  overflow: hidden;
  color: var(--text-2);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.studio .pipeline {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  list-style: none;
}
.studio .pipeline li {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--text-3);
  font-size: 12.5px;
  white-space: nowrap;
}
.studio .pipeline li::after {
  content: "";
  flex: 1;
  height: 1px;
  min-width: 8px;
  margin: 0 10px;
  background: var(--line-strong);
}
.studio .pipeline li:nth-last-child(2) {
  flex: none;
}
.studio .pipeline li:nth-last-child(2)::after,
.studio .pipeline .pipe-meta::after {
  display: none;
}
.studio .pipe-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 50%;
}
.studio .pipe-icon .ico {
  stroke-width: 2.4;
}
.studio .pipeline li.done {
  color: var(--text-2);
}
.studio .pipeline li.done::after {
  background: rgba(76, 195, 138, 0.4);
}
.studio .pipeline li.done .pipe-icon {
  border-color: transparent;
  background: var(--good-soft);
  color: var(--good);
}
.studio .pipeline li.current {
  color: var(--text);
  font-weight: 600;
}
.studio .pipeline li.current .pipe-icon {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.studio .pipeline li.current .pipe-icon::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}
.studio .pipeline li.failed {
  color: var(--bad-text);
  font-weight: 600;
}
.studio .pipeline li.failed .pipe-icon {
  border-color: transparent;
  background: var(--bad-soft);
  color: var(--bad);
}
.studio .pipeline .pipe-meta {
  flex: none;
  margin-left: 18px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
  color: var(--text-2);
  font-weight: 500;
}

.studio .run-grid {
  display: grid;
  flex: 1;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 16px;
  min-height: 0;
}
.studio .run-stage {
  display: grid;
  grid-template-rows: minmax(0, 3fr) minmax(170px, 2fr);
  gap: 16px;
  min-height: 0;
}
.studio .run-side {
  min-height: 0;
  padding: 16px 18px 20px;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}

.studio .activity {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  overflow: hidden;
}
.studio .activity-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
}
.studio .activity-head h3 {
  font-size: 13px;
  font-weight: 600;
}
.studio .activity-body {
  flex: 1;
  min-height: 0;
  padding: 6px 0;
  overflow-y: auto;
}
.studio .activity-body .empty {
  padding: 14px;
}
.studio .event {
  display: grid;
  grid-template-columns: 62px 96px minmax(0, 1fr);
  gap: 10px;
  padding: 4px 14px;
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .event:hover {
  background: rgba(255, 255, 255, 0.02);
}
.studio .event time {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11px;
  line-height: 20px;
}
.studio .event-role {
  display: flex;
  align-items: baseline;
  gap: 4px;
  overflow: hidden;
  color: var(--text-3);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.studio .event-role small {
  color: var(--text-3);
  font-size: 11px;
  font-weight: 400;
}
.studio .event-role.playtester {
  color: #8fc7f5;
}
.studio .event-role.builder {
  color: #c7b4fa;
}
.studio .event-role.fixer {
  color: #f5b98f;
}
.studio .event-role.spec {
  color: #a8dcc2;
}
.studio .event-role.benana {
  color: var(--accent);
}
.studio .event-text {
  min-width: 0;
  color: var(--text-2);
  overflow-wrap: anywhere;
}
.studio .event-text code {
  margin-right: 8px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--raised);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event-text .result {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 11.5px;
}
.studio .event.text .event-text,
.studio .event.phase .event-text {
  color: var(--text);
}
.studio .event.failure .event-text,
.studio .event.error .event-text {
  color: var(--bad-text);
}

/* ---------- Mods ---------- */

.studio .mods {
  display: grid;
  flex: 1;
  grid-template-columns: 340px minmax(0, 1fr);
  gap: 16px;
  min-height: 0;
}
.studio .mods-list {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 12px;
}
.studio .mods-list .segmented {
  align-self: flex-start;
  margin-bottom: 10px;
}
.studio .list {
  display: grid;
  align-content: start;
  gap: 1px;
  min-height: 0;
  overflow-y: auto;
}
.studio .list-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  text-align: left;
}
.studio .list-row:hover {
  background: rgba(255, 255, 255, 0.035);
}
.studio .list-row.active {
  background: rgba(255, 255, 255, 0.07);
}
.studio .list-main {
  flex: 1;
  min-width: 0;
}
.studio .list-main strong {
  display: block;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .list-main small {
  color: var(--text-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}
.studio .entire-split .list {
  padding: 0 8px 8px;
}
.studio .mods-detail {
  min-height: 0;
  padding: 20px 24px 28px;
  overflow-y: auto;
}
.studio .detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}
.studio .detail-title {
  min-width: 0;
}
.studio .overview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 36px;
  padding-top: 22px;
}
.studio .overview-col {
  min-width: 0;
}
.studio .prose {
  color: var(--text-2);
  line-height: 1.6;
}
.studio .bullets {
  margin: 10px 0 0;
  padding-left: 18px;
  color: var(--text-2);
}
.studio .bullets li {
  padding: 2px 0;
}
.studio .bullets li::marker {
  color: var(--text-3);
}

/* ---------- Code ---------- */

.studio .code {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-top: 18px;
}
.studio .code .segmented {
  align-self: flex-start;
}
.studio .code-split {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: 420px;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.studio .file-tree {
  padding: 10px 8px;
  border-right: 1px solid var(--line);
  background: var(--bg);
  overflow-y: auto;
}
.studio .tree-group + .tree-group {
  margin-top: 10px;
}
.studio .tree-group small {
  display: block;
  padding: 2px 8px 4px;
  overflow: hidden;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button {
  display: block;
  width: 100%;
  padding: 5px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .file-tree button:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.studio .file-tree button.on {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
}
.studio .commit-list button {
  display: grid;
  gap: 1px;
  font-family: var(--sans);
  font-size: 12.5px;
}
.studio .commit-list small {
  color: var(--text-3);
  font-size: 11px;
}
.studio .viewer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #0d0e11;
}
.studio .viewer-head {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  font-size: 11.5px;
}
.studio .code-body {
  flex: 1;
  max-height: 62vh;
  padding: 8px 0;
  overflow: auto;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.65;
}
.studio .code-line {
  display: flex;
  min-width: max-content;
  padding-right: 16px;
}
.studio .code-line .ln {
  flex: none;
  width: 48px;
  padding-right: 14px;
  color: #4b4f58;
  text-align: right;
  user-select: none;
}
.studio .code-line .lc {
  color: #d4d6dc;
  white-space: pre;
}
.studio .code-line:not(:has(.ln)) .lc {
  padding-left: 16px;
}
.studio .code-line.add {
  background: rgba(76, 195, 138, 0.09);
}
.studio .code-line.add .lc {
  color: #9be0bd;
}
.studio .code-line.del {
  background: rgba(229, 72, 77, 0.09);
}
.studio .code-line.del .lc {
  color: #f5a3a6;
}
.studio .code-line.hunk .lc {
  color: #8fc7f5;
}
.studio .code-line.meta .lc {
  color: var(--text-3);
}

/* ---------- Insights ---------- */

.studio .kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .kpis.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.studio .kpi {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 16px 20px;
}
.studio .kpi + .kpi {
  border-left: 1px solid var(--line);
}
.studio .kpi span {
  color: var(--text-2);
  font-size: 12px;
}
.studio .kpi strong {
  margin-top: 4px;
  color: var(--text);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.studio .kpi small {
  color: var(--text-3);
  font-size: 11.5px;
}
.studio .legend {
  display: flex;
  gap: 16px;
}
.studio .lg {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .lg::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .lg.passed::before {
  background: var(--good);
}
.studio .lg.failed::before {
  background: var(--bad);
}
.studio .lg.running::before {
  background: var(--accent);
}
.studio .chart {
  position: relative;
  margin-top: 14px;
}
.studio .daily {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.studio .daily .axis {
  stroke: var(--line-strong);
}
.studio .daily .grid {
  stroke: var(--line);
  stroke-dasharray: 2 4;
}
.studio .daily .tick {
  fill: var(--text-3);
  font-size: 11px;
}
.studio .daily .hit {
  fill: transparent;
}
.studio .daily .hover-band {
  fill: rgba(255, 255, 255, 0.04);
}
.studio .daily .passed {
  fill: var(--good);
}
.studio .daily .failed {
  fill: var(--bad);
}
.studio .daily .running {
  fill: var(--accent);
}
.studio .tooltip {
  position: absolute;
  top: 0;
  z-index: 2;
  display: grid;
  gap: 3px;
  min-width: 140px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: #1a1c21;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  pointer-events: none;
  transform: translate(-50%, -8px);
}
.studio .tooltip strong {
  margin-bottom: 2px;
  font-weight: 600;
}
.studio .tooltip span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-2);
}
.studio .tooltip i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .tooltip i.passed {
  background: var(--good);
}
.studio .tooltip i.failed {
  background: var(--bad);
}
.studio .tooltip i.running {
  background: var(--accent);
}
.studio .tooltip b {
  margin-left: auto;
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.studio .insight-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.studio .insight-grid .section-head ~ .section-head {
  margin-top: 22px;
}
.studio .hbars {
  display: grid;
  gap: 10px;
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}
.studio .hbars li {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 12px;
  color: var(--text-2);
  font-size: 12.5px;
}
.studio .hbars strong {
  color: var(--text);
  font-weight: 600;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.studio .coverage-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.studio .coverage {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .coverage .partner-dot {
  margin-top: 6px;
}
.studio .coverage strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.studio .coverage span {
  display: block;
  color: var(--text);
  font-size: 12.5px;
}
.studio .coverage small {
  color: var(--text-3);
  font-size: 11.5px;
}

/* ---------- Neatlogs and Entire ---------- */

.studio .connection {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.studio .connection strong {
  flex: none;
  font-weight: 600;
}
.studio .connection .meta {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio .split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  align-items: start;
  gap: 16px;
}
.studio .split > .panel:first-child {
  overflow-x: auto;
}
.studio .entire-split {
  grid-template-columns: 300px minmax(0, 1fr);
}
.studio .detail-card {
  position: sticky;
  top: 0;
}
.studio .trace {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.studio .trace-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.studio .trace-head strong {
  font-weight: 600;
}
.studio .spans {
  display: grid;
  gap: 1px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}
.studio .spans li {
  display: grid;
  padding: 5px 0 5px 12px;
  border-left: 2px solid rgba(79, 184, 208, 0.5);
  color: var(--text-2);
  font-size: 12px;
}
.studio .spans li.failed {
  border-left-color: var(--bad);
  color: var(--bad-text);
}
.studio .spans small {
  color: var(--text-3);
}
.studio .commits {
  margin: 0;
  padding: 0;
  list-style: none;
}
.studio .commits li {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
}
.studio .commits li:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 26px;
  bottom: -10px;
  left: 4px;
  width: 1px;
  background: var(--line-strong);
}
.studio .commit-node {
  flex: none;
  width: 9px;
  height: 9px;
  border: 2px solid var(--good);
  border-radius: 50%;
  background: var(--panel);
}
.studio .commits li.bad .commit-node {
  border-color: var(--bad);
}
.studio .commit-main {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}
