  .studio .insight-grid,
  .studio .overview,
  .studio .split,
  .studio .entire-split {
    grid-template-columns: 1fr;
  }
  .studio .mods {
    grid-template-columns: 280px minmax(0, 1fr);
  }
  .studio .flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

